const PLUGIN_INSPECT_PAUSE_MS: u64 = 600;

/// Pause in typing before an inline completion is asked for (`SPEC-0157`).
const INLINE_PAUSE_MS: u64 = 500;

/// Byte offset of char offset `chars` in `text`.
fn byte_of(text: &str, chars: usize) -> usize {
    text.char_indices()
        .nth(chars)
        .map_or(text.len(), |(b, _)| b)
}

/// Applies byte-range edits (ascending) to an editor holding `text` as one undo step; with
/// `keep_caret` the caret stays on the text it was on.
fn apply_byte_edits(
    editor: &Entity<EditorView>,
    text: &str,
    edits: &[idecraft_languages::jvm::TextEdit],
    keep_caret: bool,
    cx: &mut Context<WorkbenchView>,
) {
    let chars = |b: usize| text[..b].chars().count();
    let ranges: Vec<(std::ops::Range<usize>, String)> = edits
        .iter()
        .map(|e| (chars(e.range.start)..chars(e.range.end), e.text.clone()))
        .collect();
    editor.update(cx, |e, cx| {
        let caret = e.state.carets.primary().head;
        e.replace_ranges(&ranges, cx);
        if keep_caret {
            let shift: isize = ranges
                .iter()
                .filter(|(r, _)| r.end <= caret)
                .map(|(r, t)| t.chars().count() as isize - r.len() as isize)
                .sum();
            let at = (caret as isize + shift).max(0) as usize;
            let at = at.min(e.state.buffer.len_chars());
            e.select_range(at..at, cx);
        }
    });
}

/// A file opened from a remote host: where it lives there and the stamp last read or written.
#[derive(Debug, Clone)]
struct RemoteOpened {
    remote: idecraft_remote::Remote,
    path: String,
    stamp: String,
    /// The host's copy changed: the next save overwrites it.
    overwrite: bool,
}

pub(crate) fn c(color: Rgba) -> Hsla {
    rgba((color.rgb << 8) | u32::from(color.alpha)).into()
}

/// An open completion list: all suggestions, those matching the typed prefix, the selection and
/// where the completed identifier starts (SPEC-0072).
struct Completion {
    path: PathBuf,
    items: Vec<idecraft_languages::insight::CompletionItem>,
    shown: Vec<idecraft_languages::insight::CompletionItem>,
    selected: usize,
    start: usize,
    /// The identifier typed so far, highlighted in the labels (SPEC-0072 v5 behaviour 11).
    prefix: String,
    /// Documentation by item, `None` while asked or when there is none (behaviour 13).
    docs: HashMap<String, Option<String>>,
    /// Name suggestions at a template placeholder (SPEC-0072 v8 behaviour 32): the placeholder's
    /// text when the list opened; all names are shown while it is unchanged.
    initial: Option<String>,
    /// The expected type of a smart list, named in the hint line (v8 behaviour 26, IMP-0302).
    expected: Option<String>,
    /// Items whose detail was asked for with `completionItem/resolve` (v8 behaviour 28).
    details_asked: std::collections::HashSet<String>,
    /// Whether the classes the members come from were asked for (v10 behaviour 45).
    origins_asked: bool,
    /// The typed name when the list opened: servers filter by it, so a name that no longer
    /// extends it is asked for again (SPEC-0072 v9 behaviour 43).
    opened_with: String,
    _watch: gpui::Subscription,
}

/// The tab stops of an inserted snippet that Tab and Enter still visit (SPEC-0072 v7 behaviour 18).
struct SnippetSession {
    path: PathBuf,
    /// Char ranges of each remaining stop group, in visiting order; the first is selected.
    stops: Vec<Vec<std::ops::Range<usize>>>,
    /// The buffer length when the current stop was selected, to shift the later stops by what
    /// was typed into it.
    len: usize,
    /// The stops already left behind, the last one left last (`PreviousTemplateVariable`,
    /// SPEC-0072 v14 behaviour 51).
    visited: Vec<Vec<std::ops::Range<usize>>>,
}

/// The key of a completion item for its documentation (behaviour 13).
fn completion_key(item: &idecraft_languages::insight::CompletionItem) -> String {
    format!(
        "{}\u{1f}{}\u{1f}{}",
        item.label,
        item.label_detail.as_deref().unwrap_or_default(),
        item.detail.as_deref().unwrap_or_default()
    )
}

