    /// Status colour key of a file, `None` when it is unchanged (SPEC-0059 behaviour 7).
    pub fn file_status_key(&self, path: &Path) -> Option<&'static str> {
        self.file_status.get(path).copied()
    }

    fn file_color(&self, path: &Path) -> Option<Hsla> {
        let key = self.file_status_key(path)?;
        Palette::current().scheme_color(key).map(|c| rgb(c).into())
    }

    /// The files with errors, marked on their tabs and in the tree (SPEC-0059 v4 behaviour 10): the
    /// problems of open editors, and for files that are not open the errors the language server
    /// pool last published for them.
    pub fn problem_files(&self, cx: &gpui::App) -> crate::problem_marks::ProblemFiles {
        use crate::diagnostics_model::Severity;
        let open = self.editors.iter().map(|(path, e)| {
            let severities: Vec<Severity> =
                e.read(cx).problems().iter().map(|p| p.severity).collect();
            (path.as_path(), severities)
        });
        let unopened = self
            .pool_pending
            .iter()
            .filter(|(path, _)| !self.editors.contains_key(*path))
            .map(|(path, found)| {
                let severities: Vec<Severity> = found
                    .iter()
                    .map(|d| {
                        if crate::problem_marks::lsp_error(&d.severity) {
                            Severity::Error
                        } else {
                            Severity::Warning
                        }
                    })
                    .collect();
                (path.as_path(), severities)
            });
        crate::problem_marks::ProblemFiles::from_severities(open.chain(unopened))
    }

    /// Whether the status bar shows the Python interpreter widget: it follows the active editor
    /// (SPEC-0117 v2 behaviour 1).
    pub fn python_widget_shown(&self) -> bool {
        crate::python_widget::shown(self.python_project, self.active_path().as_deref())
    }

    /// Save or disk message of the active editor (SPEC-0058 behaviours 9–10).
    pub fn active_note(&self, cx: &gpui::App) -> Option<String> {
        self.active_editor().and_then(|e| e.read(cx).status().note)
    }

    /// The tool window whose stripe button menu is open, if any (SPEC-0275).
    pub fn stripe_menu_open(&self) -> Option<ToolWindow> {
        self.stripe_menu
    }

    /// Number of open tabs.
    pub fn tab_count(&self) -> usize {
        self.tabs.paths().len()
    }

    /// The editor of the active tab (self-tests drive it directly).
    pub fn active_editor_entity(&self) -> Option<Entity<EditorView>> {
        self.active_editor()
    }

    /// The editor open on `path`, if any (self-tests).
    pub fn editor_for(&self, path: &Path, _cx: &gpui::App) -> Option<Entity<EditorView>> {
        self.editors.get(path).cloned()
    }

    /// Text of the active editor.
    pub fn active_text(&self, cx: &gpui::App) -> Option<String> {
        self.active_editor().map(|e| e.read(cx).state.buffer.text())
    }

    /// Visible text of the terminal tool window, if it was opened.
    pub fn terminal_text(&self, cx: &gpui::App) -> Option<String> {
        self.terminal().map(|t| t.read(cx).text())
    }

    /// The shell with focus in the terminal tab shown, if any.
    pub fn terminal(&self) -> Option<Entity<TerminalView>> {
        let tab = self.terminals.get(self.terminal_tab)?;
        tab.panes.get(tab.active).map(|p| p.view.clone())
    }

    /// The shells of the terminal tab shown, in order (SPEC-0205 behaviour 3).
    pub fn terminal_panes(&self) -> Vec<Entity<TerminalView>> {
        self.terminals
            .get(self.terminal_tab)
            .map(|t| t.panes.iter().map(|p| p.view.clone()).collect())
            .unwrap_or_default()
    }

    /// Whether the shells of the tab shown are side by side (else one above the other).
    pub fn terminal_side_by_side(&self) -> bool {
        self.terminals
            .get(self.terminal_tab)
            .is_some_and(|t| t.side_by_side)
    }

    /// Names of the terminal tabs: "Local", "Local (2)", … or as renamed (SPEC-0205 behaviours 1
    /// and 2).
    pub fn terminal_tabs(&self) -> Vec<String> {
        self.terminals.iter().map(|t| t.name.clone()).collect()
    }

    /// Index of the terminal tab shown.
    pub fn terminal_tab(&self) -> usize {
        self.terminal_tab
    }

    /// The tool window layout: sides, order and stripes (SPEC-0167).
    pub fn tool_layout(&self) -> &ToolLayout {
        &self.tool_layout
    }

    /// Whether `w` has a stripe button: windows that need a session get one once they exist
    /// (SPEC-0167 behaviour 2).
    fn tool_window_exists(&self, w: ToolWindow) -> bool {
        match w {
            // Commit only in a Git repository; AI Chat always, where the reference has its AI
            // window (SPEC-0061 v10 behaviour 51).
            ToolWindow::Commit => self.branch.is_some() || self.commit.is_some(),
            ToolWindow::AiChat => true,
            ToolWindow::Run => self.run_view.is_some(),
            ToolWindow::Debug => self.debug_view.is_some(),
            // Services is on the default stripe from the start, like the reference's (SPEC-0061
            // v10 behaviour 51); it opens empty until a run or a database console shows there.
            // The former panels outside the layout get their button once they were opened
            // (SPEC-0061 v7 behaviour 43).
            ToolWindow::Find => self.find_usages.is_some(),
            ToolWindow::FindInFiles => self.find_in_files.is_some(),
            ToolWindow::Endpoints => self.endpoints.is_some(),
            ToolWindow::Spring => self.spring.is_some(),
            ToolWindow::Python => self.python.is_some(),
            ToolWindow::Containers => self.containers.is_some(),
            ToolWindow::Profiler => self.profiler.is_some(),
            ToolWindow::Remote => self.remote_view.is_some(),
            // Once it has something to show or did something (SPEC-0061 v17 behaviour 65).
            ToolWindow::Build => {
                self.has_build_files || self.build_ran || self.build_tools.is_some()
            }
            _ => true,
        }
    }

    /// The windows with a button on the left or right stripe, top to bottom: both halves, then
    /// the bottom part's windows from the foot upward (SPEC-0061 v7 behaviour 38; tests).
    pub fn stripe_windows(&self, stripe: Side) -> Vec<ToolWindow> {
        let groups = self
            .tool_layout
            .stripe_with(stripe, &self.shown_tool_windows());
        groups
            .top
            .into_iter()
            .chain(groups.split)
            .chain(groups.foot)
            .filter(|w| self.tool_window_exists(*w))
            .collect()
    }

    /// Whether `w` is shown; Commit covers Project while both are on the same side (SPEC-0063
    /// behaviour 6).
    pub fn tool_window_shown(&self, w: ToolWindow) -> bool {
        match w {
            ToolWindow::Project => {
                self.show_tree
                    && !(self.tool_window_shown(ToolWindow::Commit)
                        && self.tool_layout.shown_placement(ToolWindow::Commit)
                            == self.tool_layout.shown_placement(ToolWindow::Project))
            }
            ToolWindow::Commit => self.show_commit && self.commit.is_some(),
            ToolWindow::Git => self.git_log.is_some(),
            ToolWindow::Problems => self.show_problems,
            ToolWindow::Run => self.run_view().is_some(),
            ToolWindow::Debug => self.debug_view().is_some(),
            ToolWindow::Services => self.services_view().is_some(),
            ToolWindow::Terminal => self.show_terminal && self.terminal().is_some(),
            ToolWindow::Database => self.database_view().is_some(),
            ToolWindow::Build => self.build_tools_view().is_some(),
            ToolWindow::Plugins => self.show_plugin_panels,
            ToolWindow::Structure => self.show_structure_tool,
            ToolWindow::Find => self.find_tool_window().is_some(),
            ToolWindow::FindInFiles => self.find_in_files.is_some() && self.show_find_in_files,
            ToolWindow::Endpoints => self.endpoints_view().is_some(),
            ToolWindow::Spring => self.spring_view().is_some(),
            ToolWindow::AiChat => self.ai_chat_view().is_some(),
            ToolWindow::Python => self.python_view().is_some(),
            ToolWindow::Containers => self.containers_view().is_some(),
            ToolWindow::Profiler => self.profiler_view().is_some(),
            ToolWindow::Remote => self.remote_view().is_some(),
            ToolWindow::Bookmarks => self.show_bookmarks_tool,
            ToolWindow::Todo => self.todo.shown,
            ToolWindow::Notifications => self.notifications.shown,
        }
    }

    fn shown_tool_windows(&self) -> Vec<ToolWindow> {
        ToolWindow::ALL
            .into_iter()
            .filter(|w| self.tool_window_shown(*w))
            .collect()
    }

    fn hide_tool_window(&mut self, w: ToolWindow) {
        match w {
            ToolWindow::Project => self.show_tree = false,
            ToolWindow::Commit => self.show_commit = false,
            ToolWindow::Git => self.git_log = None,
            ToolWindow::Problems => self.show_problems = false,
            ToolWindow::Run => self.show_run = false,
            ToolWindow::Debug => self.show_debug = false,
            ToolWindow::Services => self.show_services = false,
            ToolWindow::Terminal => self.show_terminal = false,
            ToolWindow::Database => self.show_database = false,
            ToolWindow::Build => self.show_build_tools = false,
            ToolWindow::Plugins => self.show_plugin_panels = false,
            ToolWindow::Structure => self.show_structure_tool = false,
            ToolWindow::Find => self.show_find_usages = false,
            ToolWindow::FindInFiles => self.show_find_in_files = false,
            ToolWindow::Endpoints => self.show_endpoints = false,
            ToolWindow::Spring => self.show_spring = false,
            ToolWindow::AiChat => self.show_ai_chat = false,
            ToolWindow::Python => self.show_python = false,
            ToolWindow::Containers => self.show_containers = false,
            ToolWindow::Profiler => self.show_profiler = false,
            ToolWindow::Remote => self.show_remote = false,
            ToolWindow::Bookmarks => self.show_bookmarks_tool = false,
            ToolWindow::Todo => self.hide_todo_tool(),
            ToolWindow::Notifications => self.notifications.shown = false,
        }
        self.auto_hide.forget(w);
        // Hiding ends a ⌥-click into the other half (SPEC-0061 v10 behaviour 50).
        self.tool_layout.clear_shown_elsewhere(w);
    }

    /// Hides the shown windows `w` displaces in its placement, also at the bottom; Commit only
    /// covers Project (SPEC-0167 behaviour 4, SPEC-0061 v10 behaviour 49).
    fn displace_for(&mut self, w: ToolWindow) {
        let shown = self.shown_tool_windows();
        for other in self.tool_layout.displaced_by(w, &shown) {
            if !(w == ToolWindow::Commit && other == ToolWindow::Project) {
                self.hide_tool_window(other);
            }
        }
    }

    /// Shows or hides a tool window of the layout as its activation action does, hiding the other
    /// window of its side when it is shown on the left or right (SPEC-0167 behaviours 2 and 4).
    pub fn toggle_tool_window(
        &mut self,
        w: ToolWindow,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let was = self.tool_window_shown(w);
        let focused = was && self.tool_window_focused(w, window, cx);
        // A shown window without the focus gets it; only a focused one hides (hand test 7 of
        // round 4: ⌘6 left the keys in the editor).
        if idecraft_ui::tool_windows::Activation::of(was, focused)
            == idecraft_ui::tool_windows::Activation::Focus
            && let Some(focus) = self.tool_window_focus(w, cx)
        {
            // The popups of the editor do not take the keys meant for the window.
            self.close_editor_popups();
            window.focus(&focus);
            cx.notify();
            return;
        }
        if !was {
            self.displace_for(w);
            self.tool_layout.forget_hidden();
            self.close_editor_popups();
            // A window off the sidebar gets a button only while it is shown; showing it does not
            // add it (SPEC-0061 v10 behaviour 52, formerly v7 behaviour 40).
        }
        match w {
            ToolWindow::Project => {
                if !was {
                    self.show_tree = true;
                    window.focus(&self.tree_focus);
                } else if self.tree_focus.is_focused(window) {
                    self.show_tree = false;
                    self.focus_active(window, cx);
                } else {
                    window.focus(&self.tree_focus);
                }
                cx.notify();
            }
            ToolWindow::Commit => self.toggle_commit(window, cx),
            ToolWindow::Git => self.toggle_git_log(window, cx),
            ToolWindow::Problems => self.toggle_problems(window, cx),
            ToolWindow::Run => self.toggle_run_window(window, cx),
            ToolWindow::Debug => self.toggle_debug_window(window, cx),
            ToolWindow::Services => self.toggle_services(window, cx),
            ToolWindow::Terminal => self.toggle_terminal(window, cx),
            ToolWindow::Database => self.toggle_database(window, cx),
            ToolWindow::Build => self.toggle_build_tools(window, cx),
            ToolWindow::Plugins => self.toggle_plugin_panels(window, cx),
            ToolWindow::Structure => self.toggle_structure_tool(window, cx),
            ToolWindow::Find => {
                if self.find_usages.is_some() {
                    self.toggle_flag_window(w, window, cx);
                } else {
                    self.status = Some("No usages searched yet (⌥F7)".into());
                    cx.notify();
                }
            }
            ToolWindow::FindInFiles => {
                if self.find_in_files.is_some() {
                    self.toggle_flag_window(w, window, cx);
                } else {
                    self.open_find_in_files(window, cx);
                }
            }
            ToolWindow::Endpoints => self.toggle_endpoints(window, cx),
            ToolWindow::Spring => self.toggle_spring(window, cx),
            ToolWindow::AiChat => self.show_ai_chat(true, window, cx),
            ToolWindow::Python => self.toggle_python(window, cx),
            ToolWindow::Containers => self.toggle_containers(window, cx),
            ToolWindow::Profiler => self.toggle_profiler(window, cx),
            ToolWindow::Remote => self.toggle_remote(window, cx),
            ToolWindow::Bookmarks => self.toggle_bookmarks_tool(window, cx),
            ToolWindow::Todo => self.toggle_todo_tool(window, cx),
            ToolWindow::Notifications => self.toggle_notifications(cx),
        }
    }

    /// Shows a window whose view exists and focuses it, or hides it and focuses the editor
    /// (Find, Find in Files; SPEC-0061 v7 behaviour 43).
    fn toggle_flag_window(&mut self, w: ToolWindow, window: &mut Window, cx: &mut Context<Self>) {
        if self.tool_window_shown(w) {
            self.hide_tool_window(w);
            self.focus_active(window, cx);
        } else {
            match w {
                ToolWindow::Find => self.show_find_usages = true,
                ToolWindow::FindInFiles => self.show_find_in_files = true,
                _ => {}
            }
            if let Some(focus) = self.tool_window_focus(w, cx) {
                window.focus(&focus);
            }
        }
        cx.notify();
    }

    /// The focus handle of tool window `w`'s content, if it has one.
    fn tool_window_focus(&self, w: ToolWindow, cx: &gpui::App) -> Option<FocusHandle> {
        match w {
            ToolWindow::Project => Some(self.tree_focus.clone()),
            ToolWindow::Commit => self.commit.as_ref().map(|v| v.read(cx).focus(cx)),
            ToolWindow::Git => self.git_log.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Problems => Some(self.problems_focus.clone()),
            ToolWindow::Run => self.run_view.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Debug => self.debug_view.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Services => self.services.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Terminal => self.terminal().map(|t| t.read(cx).focus()),
            ToolWindow::Database => self.database.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Build => self.build_tools.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Plugins => None,
            ToolWindow::Structure => self.structure_tool.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Find => self.find_usages.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::FindInFiles => self.find_in_files.as_ref().map(|v| v.read(cx).focus(cx)),
            ToolWindow::Endpoints => self.endpoints.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Spring => self.spring.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::AiChat => self.ai_chat.as_ref().map(|v| v.read(cx).focus(cx)),
            ToolWindow::Python => self.python.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Containers => self.containers.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Profiler => self.profiler.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Remote => self.remote_view.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Bookmarks => self.bookmarks_tool.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Todo => self.todo.tool.as_ref().map(|v| v.read(cx).focus()),
            ToolWindow::Notifications => None,
        }
    }

    /// The focus handle around all of tool window `w`'s content, where that is not the handle
    /// [`Self::tool_window_focus`] gives: the Commit window focuses its message field, AI Chat
    /// its input, while their lists and buttons hold the focus on the view's own handle
    /// (`SPEC-0067` v12 behaviour 21).
    fn tool_window_scope(&self, w: ToolWindow, cx: &gpui::App) -> Option<FocusHandle> {
        use gpui::Focusable as _;
        match w {
            ToolWindow::Commit => self.commit.as_ref().map(|v| v.read(cx).focus_handle(cx)),
            ToolWindow::AiChat => self.ai_chat.as_ref().map(|v| v.read(cx).scope()),
            _ => None,
        }
    }

    /// Whether the keyboard focus is in tool window `w`: on the element the window focuses when
    /// it is activated or on any other element of its content (a list, a tree, a field).
    pub fn tool_window_focused(&self, w: ToolWindow, window: &Window, cx: &gpui::App) -> bool {
        self.tool_window_scope(w, cx)
            .into_iter()
            .chain(self.tool_window_focus(w, cx))
            .any(|f| f.contains_focused(window, cx))
    }

    /// The shown tool window that holds the keyboard focus, with the element that holds it: what
    /// Search Everywhere gives the focus back to (`SPEC-0067` v12 behaviour 21).
    pub fn tool_window_focus_place(
        &self,
        window: &Window,
        cx: &gpui::App,
    ) -> Option<(ToolWindow, Option<FocusHandle>)> {
        self.focused_tool_window(window, cx)
            .map(|w| (w, window.focused(cx)))
    }

    /// Closes the completion list, the parameter info and the documentation popup of the editor:
    /// they take Up, Down, Enter and Escape only while the editor has the focus.
    fn close_editor_popups(&mut self) {
        self.completion = None;
        self.params = None;
        self.doc = None;
    }

    /// Docks `w` to `side`, last there, and saves the layout; a shown window stays shown
    /// (SPEC-0167 behaviours 5 and 8).
    pub fn move_tool_window(&mut self, w: ToolWindow, side: Side, cx: &mut Context<Self>) {
        if self.tool_layout.move_to(w, side) {
            if self.tool_window_shown(w) {
                self.displace_for(w);
            }
            self.save_tool_layout();
            self.status = Some(format!("{} moved to the {}", w.title(), side.name()));
        }
        cx.notify();
    }

    fn save_tool_layout(&mut self) {
        if let Err(e) = self.tool_layout.save(&self.root) {
            self.status = Some(format!("Tool window layout not saved: {e}"));
        }
    }

    /// Puts `w` in view mode `mode`, saves the layout and shows the window in it (SPEC-0061 v7
    /// behaviour 39).
    pub fn set_tool_window_mode(
        &mut self,
        w: ToolWindow,
        mode: ViewMode,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.header_menu = None;
        self.header_submenu = None;
        self.stripe_menu = None;
        if self.tool_layout.set_mode(w, mode) {
            self.auto_hide.forget(w);
            if self.maximized.is_some_and(|(m, _)| m == w) {
                self.maximized = None;
            }
            self.save_tool_layout();
            self.status = Some(format!("{}: {}", w.title(), mode.label()));
        }
        if !self.tool_window_shown(w) {
            self.toggle_tool_window(w, window, cx);
        }
        cx.notify();
    }

    /// Docks `w` to `placement`, last there, and saves the layout; a shown window stays shown and
    /// hides the shown window of its new half (SPEC-0061 v7 behaviour 37).
    pub fn place_tool_window(
        &mut self,
        w: ToolWindow,
        placement: Placement,
        cx: &mut Context<Self>,
    ) {
        self.header_menu = None;
        self.header_submenu = None;
        self.stripe_menu = None;
        if self.tool_layout.place(w, placement) {
            if self.tool_window_shown(w) {
                self.displace_for(w);
            }
            self.save_tool_layout();
            self.status = Some(format!("{} moved to {}", w.title(), placement.label()));
        }
        cx.notify();
    }

    /// ⌥-click on `w`'s stripe button: shows it in the other half of its side for as long as it
    /// is shown, replacing the window there, without changing its saved placement; a window shown
    /// in its own half moves over, one shown in the other half hides (SPEC-0061 v10 behaviour 50,
    /// IMP-0311).
    pub fn alt_click_tool_window(
        &mut self,
        w: ToolWindow,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.stripe_menu = None;
        self.header_menu = None;
        if self.tool_window_shown(w) {
            if self.tool_layout.is_shown_elsewhere(w) {
                self.hide_tool_window(w);
                self.focus_active(window, cx);
            } else {
                self.tool_layout.show_in_other_half(w);
                self.displace_for(w);
                if let Some(focus) = self.tool_window_focus(w, cx) {
                    window.focus(&focus);
                }
            }
            cx.notify();
            return;
        }
        self.tool_layout.show_in_other_half(w);
        self.toggle_tool_window(w, window, cx);
        // The window was shown here, not elsewhere: nothing to keep.
        if !self.tool_window_shown(w) {
            self.tool_layout.clear_shown_elsewhere(w);
        }
        cx.notify();
    }

    /// Hides `w` and takes its stripe button away ("Remove from Sidebar", SPEC-0061 v7
    /// behaviour 40).
    pub fn remove_tool_window_from_sidebar(&mut self, w: ToolWindow, cx: &mut Context<Self>) {
        self.header_menu = None;
        self.header_submenu = None;
        self.stripe_menu = None;
        if self.tool_window_shown(w) {
            self.hide_tool_window(w);
        }
        if self.tool_layout.remove(w) {
            self.save_tool_layout();
            self.status = Some(format!("{} removed from the sidebar", w.title()));
        }
        cx.notify();
    }

    /// Hides `w` as its stripe button or Hide in its header does, also when the keys are in
    /// its separate window (SPEC-0061 v7 behaviour 39).
    pub fn hide_shown_tool_window(
        &mut self,
        w: ToolWindow,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.tool_window_shown(w) {
            self.hide_tool_window(w);
            self.focus_active(window, cx);
        }
        cx.notify();
    }

    /// Brings `w`'s stripe button back or adds it ("Add to Sidebar", SPEC-0061 v7 behaviour 40,
    /// v10 behaviour 52).
    pub fn restore_tool_window_to_sidebar(&mut self, w: ToolWindow, cx: &mut Context<Self>) {
        self.header_menu = None;
        self.header_submenu = None;
        self.stripe_menu = None;
        if self.tool_layout.restore(w) {
            self.save_tool_layout();
            self.status = Some(format!("{} added to the sidebar", w.title()));
        }
        cx.notify();
    }

    /// Opens or closes the More tool windows popup (SPEC-0061 v7 behaviour 41).
    pub fn toggle_more_tool_windows(&mut self, cx: &mut Context<Self>) {
        self.more_menu = !self.more_menu;
        self.stripe_menu = None;
        self.header_menu = None;
        cx.notify();
    }

    /// A click on `w`'s row of the More tool windows popup: the popup closes and the window is
    /// shown in its placement, replacing the one there, or hidden when it was shown; it is not
    /// added to the sidebar (SPEC-0061 v10 behaviour 53).
    pub fn choose_more_tool_window(
        &mut self,
        w: ToolWindow,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.more_menu = false;
        // A Spring window that is marked as shown but was never painted is not there for the
        // user: the row shows it instead of hiding what nobody sees (SPEC-0115 v6 behaviour 18).
        let unseen = w == ToolWindow::Spring
            && self
                .spring_view()
                .is_some_and(|v| v.read(cx).painted().0 == 0);
        if unseen {
            self.show_spring = false;
        }
        if self.tool_window_shown(w) {
            self.hide_tool_window(w);
            self.focus_active(window, cx);
        } else {
            self.toggle_tool_window(w, window, cx);
        }
        cx.notify();
    }

    /// Whether the More tool windows popup is open.
    pub fn more_tool_windows_open(&self) -> bool {
        self.more_menu
    }

    /// The entries of the More tool windows popup: every tool window that can be opened now —
    /// all but Run and Debug without a session — by title (SPEC-0061 v10 behaviour 53).
    pub fn more_tool_windows_listed(&self) -> Vec<ToolWindow> {
        let openable: Vec<ToolWindow> = ToolWindow::ALL
            .into_iter()
            .filter(|w| match w {
                ToolWindow::Run | ToolWindow::Debug | ToolWindow::Commit => {
                    self.tool_window_exists(*w)
                }
                _ => true,
            })
            .collect();
        idecraft_ui::tool_windows::more_tool_windows(&openable)
    }

    /// The tool windows shown in a separate window of their own (SPEC-0061 v7 behaviour 39).
    pub fn floating_windows(&self) -> Vec<ToolWindow> {
        self.floats.iter().map(|(w, _)| *w).collect()
    }

    /// How many of those windows are still open.
    pub fn floating_window_count(&self, cx: &gpui::App) -> usize {
        let open = cx.windows();
        self.floats
            .iter()
            .filter(|(_, h)| open.iter().any(|o| o.window_id() == h.window_id()))
            .count()
    }

    /// The header and content of `w` for its separate window, while it is shown in Float or
    /// Window mode (SPEC-0061 v7 behaviour 39).
    pub fn floating_body(
        &self,
        w: ToolWindow,
        window: &Window,
        cx: &mut Context<Self>,
    ) -> Option<gpui::AnyElement> {
        if !self.tool_layout.mode(w).separate() || !self.tool_window_shown(w) {
            return None;
        }
        self.tool_window_body(w, window, cx)
    }

    /// The user closed `w`'s separate window: its frame is kept and the tool window hidden.
    pub fn floating_closed(&mut self, w: ToolWindow, frame: Rect, cx: &mut Context<Self>) {
        self.floats.retain(|(f, _)| *f != w);
        self.tool_layout.set_bounds(w, frame);
        if self.tool_window_shown(w) {
            self.hide_tool_window(w);
        }
        self.save_tool_layout();
        cx.notify();
    }

    /// Keeps the view modes in step with what is shown, once per frame (SPEC-0061 v7
    /// behaviours 39, 40, 42 and 44): a shown window gets its stripe button back, a Dock Unpinned
    /// window that lost the focus hides, Float and Window windows open and close their own
    /// window, the Structure window follows the active tab, and the traffic lights keep their
    /// pitch.
    fn sync_tool_windows(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let mut shown = self.shown_tool_windows();
        // One window per placement, whichever way a window became shown (a run session opening
        // Run, a search opening Find, an action that sets its flag): the newcomer replaces the
        // window of its placement (SPEC-0061 v10 behaviour 49).
        let focused = self.focused_tool_window(window, cx);
        let displaced = self
            .tool_layout
            .newcomers_displace(&self.last_shown, &shown, focused);
        for w in displaced {
            if !(w == ToolWindow::Project && shown.contains(&ToolWindow::Commit)) {
                self.hide_tool_window(w);
            }
        }
        if !shown.is_empty() {
            shown = self.shown_tool_windows();
        }
        // A ⌥-click exception ends once its window is hidden (behaviour 50).
        for w in ToolWindow::ALL {
            if !shown.contains(&w) {
                self.tool_layout.clear_shown_elsewhere(w);
            }
        }
        self.last_shown = shown.clone();
        let active = window.is_window_active();
        for w in &shown {
            if self.tool_layout.mode(*w).hides_on_focus_loss() {
                let focused = self.tool_window_focused(*w, window, cx);
                if self.auto_hide.observe(*w, focused, active) {
                    let w = *w;
                    cx.defer_in(window, move |this, _, cx| {
                        if this.tool_layout.mode(w).hides_on_focus_loss() {
                            this.hide_tool_window(w);
                            cx.notify();
                        }
                    });
                }
            }
        }
        // Separate windows: open the missing ones, close those no longer wanted.
        let wanted: Vec<ToolWindow> = shown
            .iter()
            .copied()
            .filter(|w| self.tool_layout.mode(*w).separate())
            .collect();
        let stale: Vec<(ToolWindow, gpui::AnyWindowHandle)> = self
            .floats
            .iter()
            .filter(|(w, _)| !wanted.contains(w))
            .copied()
            .collect();
        // A mode change between Float and Window needs a new window of the other kind.
        let rekind: Vec<(ToolWindow, gpui::AnyWindowHandle)> = self
            .floats
            .iter()
            .filter(|(w, _)| wanted.contains(w))
            .filter(|(w, _)| {
                self.float_kinds
                    .iter()
                    .any(|(k, m)| k == w && *m != self.tool_layout.mode(*w))
            })
            .copied()
            .collect();
        for (w, handle) in stale.into_iter().chain(rekind) {
            self.floats.retain(|(f, _)| *f != w);
            self.float_kinds.retain(|(f, _)| *f != w);
            cx.defer_in(window, move |this, _, cx| {
                let frame = handle
                    .update(cx, |_, window, _| {
                        let frame = crate::floating::rect(window.bounds());
                        window.remove_window();
                        frame
                    })
                    .ok();
                if let Some(frame) = frame {
                    this.tool_layout.set_bounds(w, frame);
                    this.save_tool_layout();
                }
            });
        }
        for w in wanted {
            if !self.floats.iter().any(|(f, _)| *f == w) && !self.float_opening.contains(&w) {
                self.float_opening.push(w);
                cx.defer_in(window, move |this, window, cx| {
                    this.open_floating(w, window, cx)
                });
            }
        }
        // The Structure window follows the active tab.
        if self.tool_window_shown(ToolWindow::Structure)
            && self.structure_tool_for != self.active_path()
        {
            self.structure_tool_for = self.active_path();
            cx.defer_in(window, |this, window, cx| {
                this.load_structure_tool(window, cx)
            });
        }
        let at = (window.bounds(), active);
        if self.traffic_lights_at != Some(at) {
            self.traffic_lights_at = Some(at);
            crate::traffic_lights::space(window);
        }
    }

    /// Opens the separate window of `w` (SPEC-0061 v7 behaviour 39): at its saved frame while
    /// that is on a display, else its docked size centred on this window (IMP-0313).
    fn open_floating(&mut self, w: ToolWindow, window: &mut Window, cx: &mut Context<Self>) {
        self.float_opening.retain(|f| *f != w);
        let mode = self.tool_layout.mode(w);
        if !mode.separate()
            || !self.tool_window_shown(w)
            || self.floats.iter().any(|(f, _)| *f == w)
        {
            return;
        }
        let main = crate::floating::rect(window.bounds());
        let gap = Palette::current().island_gap;
        let size = match self.tool_layout.side(w) {
            Side::Bottom => (
                (main.w * 0.6).max(480.0),
                self.tool_layout
                    .size(w)
                    .unwrap_or(idecraft_ui::tool_windows::DEFAULT_WEIGHT * main.h - gap),
            ),
            _ => (
                self.tool_layout
                    .size(w)
                    .unwrap_or_else(|| w.width_in(main.w, gap)),
                main.h * 0.7,
            ),
        };
        let displays: Vec<Rect> = cx
            .displays()
            .iter()
            .map(|d| crate::floating::rect(d.bounds()))
            .collect();
        let frame = idecraft_ui::tool_windows::float_bounds(
            self.tool_layout.bounds(w),
            &displays,
            main,
            size,
        );
        let options = gpui::WindowOptions {
            window_bounds: Some(gpui::WindowBounds::Windowed(gpui::Bounds::new(
                gpui::point(px(frame.x), px(frame.y)),
                gpui::size(px(frame.w), px(frame.h)),
            ))),
            titlebar: Some(gpui::TitlebarOptions {
                title: Some(w.title().into()),
                appears_transparent: false,
                traffic_light_position: None,
            }),
            kind: if mode == ViewMode::Float {
                gpui::WindowKind::Floating
            } else {
                gpui::WindowKind::Normal
            },
            app_id: Some(idecraft_ui::brand::APP_ID.to_owned()),
            ..Default::default()
        };
        // GPUI draws a new window at once, and its view reads this workbench: open it outside
        // this update.
        let bench = cx.entity();
        self.float_opening.push(w);
        cx.spawn(async move |this, cx| {
            let opened = cx.update(|cx| {
                cx.open_window(options, move |fw, cx| {
                    crate::x11_wake::until_first_frame(fw);
                    cx.new(|cx| crate::floating::FloatingToolWindow::new(bench, w, fw, cx))
                })
            });
            let _ = this.update(cx, |this, cx| {
                this.float_opening.retain(|f| *f != w);
                match opened {
                    Ok(Ok(handle)) => {
                        this.floats.push((w, handle.into()));
                        this.float_kinds.retain(|(f, _)| *f != w);
                        this.float_kinds.push((w, mode));
                    }
                    Ok(Err(e)) => {
                        this.status = Some(format!("{} could not open its window: {e}", w.title()));
                    }
                    Err(_) => {}
                }
                cx.notify();
            });
        })
        .detach();
    }

    /// Shows the Structure tool window with the active file's symbols and focuses it, or hides it
    /// (`ActivateStructureToolWindow`, SPEC-0061 v7 behaviour 42).
    fn toggle_structure_tool(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.show_structure_tool {
            self.show_structure_tool = false;
            self.focus_active(window, cx);
            cx.notify();
            return;
        }
        self.show_structure_tool = true;
        self.structure_tool_for = self.active_path();
        if let Some(v) = &self.structure_tool {
            window.focus(&v.read(cx).focus());
        }
        self.load_structure_tool(window, cx);
        cx.notify();
    }

    /// The Structure tool window's list, if it has one (self-tests).
    pub fn structure_tool_window(&self) -> Option<Entity<StructureView>> {
        self.structure_tool.clone()
    }

    /// Loads the symbols of the active editor's file into the Structure tool window, as the File
    /// Structure popup does (SPEC-0079), keeping the focus where it was (SPEC-0061 v7
    /// behaviour 42).
    fn load_structure_tool(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let (Some(here), Some(editor)) = (self.here(cx), self.active_editor()) else {
            self.structure_tool = None;
            cx.notify();
            return;
        };
        if idecraft_languages::LanguageId::detect(&here.path).is_none() {
            self.structure_tool = None;
            cx.notify();
            return;
        }
        let text = editor.read(cx).state.buffer.text();
        let root = self.root.clone();
        cx.spawn_in(window, async move |this, cx| {
            let file = here.path.clone();
            let found = cx
                .background_spawn(async move {
                    let rt = tokio::runtime::Builder::new_current_thread()
                        .enable_all()
                        .build()
                        .map_err(|e| e.to_string())?;
                    rt.block_on(idecraft_languages::insight::symbols_in(
                        &root,
                        &file,
                        Some(&text),
                        std::time::Duration::from_secs(30),
                    ))
                    .map_err(|e| e.to_string())
                })
                .await;
            let _ = this.update_in(cx, |this, window, cx| {
                // The tab changed again meanwhile: a newer load follows.
                if this.structure_tool_for.as_deref() != Some(here.path.as_path()) {
                    return;
                }
                let symbols = found
                    .map(crate::structure_model::without_packages)
                    .ok()
                    .filter(|s| !s.is_empty());
                let Some(symbols) = symbols else {
                    this.structure_tool = None;
                    cx.notify();
                    return;
                };
                let had_focus = this
                    .structure_tool
                    .as_ref()
                    .is_some_and(|v| v.read(cx).focus().contains_focused(window, cx));
                let name = here
                    .path
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default();
                let caret = (here.line as u64, here.column as u64);
                let view = cx.new(|cx| {
                    let mut v = StructureView::new(&name, symbols, caret, cx);
                    v.set_docked(true);
                    v
                });
                this._structure_tool_events = Some(cx.subscribe_in(
                    &view,
                    window,
                    move |this, view, event: &StructureEvent, window, cx| {
                        match event {
                            // The window stays open (behaviour 42).
                            StructureEvent::Open(line, character) => {
                                this.remember_place(cx);
                                if let Some(editor) = this.active_editor() {
                                    let (line, column) = (*line as usize, *character as usize);
                                    editor.update(cx, |e, cx| e.go_to(line, column, cx));
                                }
                            }
                            StructureEvent::OpenAt(path, line, character) => {
                                this.remember_place(cx);
                                let place = Place {
                                    path: path.clone(),
                                    line: *line as usize,
                                    column: *character as usize,
                                };
                                this.show_place(&place, window, cx);
                            }
                            StructureEvent::Inherited => {
                                this.request_inherited(view.clone(), window, cx);
                            }
                            StructureEvent::Close => this.focus_active(window, cx),
                        }
                        cx.notify();
                    },
                ));
                if had_focus || this.structure_tool.is_none() && this.show_structure_tool {
                    window.focus(&view.read(cx).focus());
                }
                this.structure_tool = Some(view);
                cx.notify();
            });
        })
        .detach();
    }

    /// Hides every shown tool window, or brings back the ones the last call hid
    /// (`HideAllWindows`, SPEC-0167 behaviour 6).
    pub fn hide_all_tool_windows(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let mut shown = self.shown_tool_windows();
        // A tree covered by Commit would show once Commit hides; it is hidden (and restored) too.
        if self.show_tree && !shown.is_empty() && !shown.contains(&ToolWindow::Project) {
            shown.insert(0, ToolWindow::Project);
        }
        match self.tool_layout.hide_all(&shown) {
            HideAll::Hide(ws) => {
                for w in ws {
                    self.hide_tool_window(w);
                }
                self.focus_active(window, cx);
            }
            HideAll::Restore(ws) => {
                for w in &ws {
                    if !self.tool_window_shown(*w) {
                        self.toggle_tool_window(*w, window, cx);
                    }
                }
                self.focus_active(window, cx);
            }
        }
        cx.notify();
    }

    /// Hides every window shown at the bottom, so that the next one shown there gets the whole
    /// bottom; the self-test's real clicks need a list's rows painted inside its window (eight
    /// stacked bottom windows leave each about three rows). [`Self::restore_bottom_windows`] shows
    /// them again.
    pub fn hide_bottom_windows(&mut self, cx: &mut Context<Self>) -> HiddenBottom {
        let layout: Vec<ToolWindow> = self
            .tool_layout
            .on(Side::Bottom)
            .into_iter()
            .filter(|w| self.tool_window_shown(*w))
            .collect();
        let git_log = if layout.contains(&ToolWindow::Git) {
            self.git_log.clone()
        } else {
            None
        };
        for w in &layout {
            self.hide_tool_window(*w);
        }
        let mut flags = [false; BOTTOM_FLAGS];
        for (i, shown) in flags.iter_mut().enumerate() {
            let flag = self.bottom_flag(i);
            *shown = std::mem::take(flag);
        }
        let hidden = HiddenBottom {
            layout,
            flags,
            git_log,
            hierarchy: self.hierarchy.take(),
        };
        cx.notify();
        hidden
    }

    /// Shows the bottom windows [`Self::hide_bottom_windows`] hid.
    pub fn restore_bottom_windows(&mut self, hidden: HiddenBottom, cx: &mut Context<Self>) {
        for w in hidden.layout {
            match w {
                ToolWindow::Project => self.show_tree = true,
                ToolWindow::Commit => self.show_commit = true,
                ToolWindow::Problems => self.show_problems = true,
                ToolWindow::Run => self.show_run = true,
                ToolWindow::Debug => self.show_debug = true,
                ToolWindow::Services => self.show_services = true,
                ToolWindow::Terminal => self.show_terminal = true,
                ToolWindow::Database => self.show_database = true,
                ToolWindow::Build => self.show_build_tools = true,
                ToolWindow::Plugins => self.show_plugin_panels = true,
                ToolWindow::Structure => self.show_structure_tool = true,
                ToolWindow::Find => self.show_find_usages = true,
                ToolWindow::FindInFiles => self.show_find_in_files = true,
                ToolWindow::Endpoints => self.show_endpoints = true,
                ToolWindow::Spring => self.show_spring = true,
                ToolWindow::AiChat => self.show_ai_chat = true,
                ToolWindow::Python => self.show_python = true,
                ToolWindow::Containers => self.show_containers = true,
                ToolWindow::Profiler => self.show_profiler = true,
                ToolWindow::Remote => self.show_remote = true,
                ToolWindow::Bookmarks => self.show_bookmarks_tool = true,
                // Shown again only with its view: the scans start when the action shows it.
                ToolWindow::Todo => self.todo.shown = self.todo.tool.is_some(),
                ToolWindow::Notifications => self.notifications.shown = true,
                ToolWindow::Git => {
                    if self.git_log.is_none() {
                        self.git_log = hidden.git_log.clone();
                    }
                }
            }
        }
        for (i, shown) in hidden.flags.into_iter().enumerate() {
            *self.bottom_flag(i) |= shown;
        }
        if self.hierarchy.is_none() {
            self.hierarchy = hidden.hierarchy;
        }
        cx.notify();
    }

    /// The shown flags of the bottom windows outside the tool-window layout (Containers excepted).
    fn bottom_flag(&mut self, i: usize) -> &mut bool {
        match i {
            0 => &mut self.show_find_usages,
            1 => &mut self.show_endpoints,
            2 => &mut self.show_spring,
            3 => &mut self.show_ai_chat,
            4 => &mut self.show_python,
            5 => &mut self.show_profiler,
            6 => &mut self.show_remote,
            _ => &mut self.show_find_in_files,
        }
    }

    /// Hides or shows both stripes (`ViewToolButtons`, SPEC-0167 behaviour 7).
    pub fn toggle_tool_window_bars(&mut self, cx: &mut Context<Self>) {
        self.tool_layout.stripes = !self.tool_layout.stripes;
        self.save_tool_layout();
        cx.notify();
    }

    /// Shows the terminal tool window and focuses it, or hides it when it already has focus
    /// (`ActivateTerminalToolWindow`, SPEC-0062 behaviour 5); the first time the saved tabs come
    /// back (SPEC-0205 behaviour 6).
    fn toggle_terminal(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let focused = self
            .terminal()
            .is_some_and(|t| t.read(cx).focus().is_focused(window));
        if self.show_terminal && focused {
            self.show_terminal = false;
            self.focus_active(window, cx);
        } else {
            if self.terminals.is_empty() && !self.restore_terminals(window, cx) {
                self.add_terminal_tab(None, None, window, cx);
            }
            self.show_terminal = true;
            self.focus_terminal(window, cx);
        }
        cx.notify();
    }

    /// Focuses the shell with focus in the tab shown.
    fn focus_terminal(&self, window: &mut Window, cx: &mut Context<Self>) {
        if let Some(t) = self.terminal() {
            window.focus(&t.read(cx).focus());
        }
    }

    /// Opens another terminal tab with a new shell and shows it (`Terminal.NewTab`, ⌘T in the
    /// terminal; SPEC-0062 v2 behaviour 7).
    pub fn new_terminal_tab(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        // The saved tabs come back first; the new one is added to them.
        self.restore_terminals(window, cx);
        self.add_terminal_tab(None, None, window, cx);
        self.show_terminal = true;
        self.focus_terminal(window, cx);
        self.save_terminals(cx);
        cx.notify();
    }

    /// Adds a tab with one shell (`view`, else the user's shell in the project folder) and shows
    /// it; `name` instead of the next "Local (n)" (a container's exec, SPEC-0240).
    fn add_terminal_tab(
        &mut self,
        view: Option<Entity<TerminalView>>,
        name: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let root = self.root.clone();
        // A remote project's terminals run on its host (SPEC-0318 v2 detail 2).
        let view = view.or_else(|| self.remote_terminal_view(".", cx));
        let view = view.unwrap_or_else(|| cx.new(|cx| TerminalView::new(root, cx)));
        let name = name.unwrap_or_else(|| match self.remote_project() {
            Some((host, _)) => remote_host::host_tab_name(&host, &self.terminal_tabs()),
            None => idecraft_terminal::next_tab_name(&self.terminal_tabs()),
        });
        let pane = self.terminal_pane(view, window, cx);
        self.terminals.push(TerminalTab {
            name,
            panes: vec![pane],
            side_by_side: true,
            active: 0,
        });
        self.terminal_tab = self.terminals.len() - 1;
        self.sync_terminal_labels(cx);
    }

    /// Wraps `view` as a shell of a tab and listens to its keys and its end.
    fn terminal_pane(
        &mut self,
        view: Entity<TerminalView>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> TerminalPane {
        let events = cx.subscribe_in(
            &view,
            window,
            |this, view, event: &crate::terminal_view::TerminalEvent, window, cx| match event {
                crate::terminal_view::TerminalEvent::NewTab => this.new_terminal_tab(window, cx),
                crate::terminal_view::TerminalEvent::Close => {
                    this.close_terminal_view(view, window, cx)
                }
                crate::terminal_view::TerminalEvent::Split(side_by_side) => {
                    if let Some((tab, pane)) = this.locate_terminal(view) {
                        this.terminal_tab = tab;
                        this.terminals[tab].active = pane;
                    }
                    this.split_terminal(*side_by_side, window, cx);
                }
                crate::terminal_view::TerminalEvent::FocusSibling(forward) => {
                    this.focus_terminal_sibling(*forward, window, cx)
                }
                crate::terminal_view::TerminalEvent::ContextMenu(at) => {
                    if let Some((tab, pane)) = this.locate_terminal(view) {
                        this.terminal_tab = tab;
                        this.terminals[tab].active = pane;
                    }
                    this.open_context_menu(MenuPlace::Terminal, None, *at, cx);
                }
                crate::terminal_view::TerminalEvent::OpenFile(path, line, column) => {
                    this.open(path, window, cx);
                    if let (Some(line), Some(e)) = (line, this.active_editor()) {
                        let column = column.unwrap_or(1);
                        e.update(cx, |e, cx| e.go_to(line - 1, column - 1, cx));
                    }
                    this.focus_active(window, cx);
                }
            },
        );
        // A click into a shell makes it the one with focus of its tab.
        let focus = view.read(cx).focus();
        let focused = cx.on_focus(&focus, window, {
            let view = view.clone();
            move |this, _, cx| {
                if let Some((tab, pane)) = this.locate_terminal(&view) {
                    this.terminals[tab].active = pane;
                    cx.notify();
                }
            }
        });
        TerminalPane {
            view,
            group: 0,
            _events: [events, focused],
        }
    }

    /// Tab and position of the shell `view`.
    fn locate_terminal(&self, view: &Entity<TerminalView>) -> Option<(usize, usize)> {
        self.terminals
            .iter()
            .enumerate()
            .find_map(|(i, t)| t.panes.iter().position(|p| &p.view == view).map(|j| (i, j)))
    }

    /// Starts a shell next to the one with focus, in its current folder: to the right
    /// (`side_by_side`) or below (`Terminal.SplitVertically`/`SplitHorizontally`, ⌘D/⇧⌘D;
    /// SPEC-0205 behaviour 3). The tab's first split decides the outer direction; a split across
    /// it stacks the new shell in the cell of the one with focus (D47).
    pub fn split_terminal(
        &mut self,
        side_by_side: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(current) = self.terminal() else {
            return;
        };
        let cwd = current.read(cx).current_dir();
        // The host shell's folder is not known here: a split starts in the project folder.
        let view = match self.remote_terminal_view(".", cx) {
            Some(v) => v,
            None => cx.new(|cx| TerminalView::new(cwd, cx)),
        };
        let mut pane = self.terminal_pane(view, window, cx);
        let tab = &mut self.terminals[self.terminal_tab];
        if tab.panes.len() == 1 {
            tab.side_by_side = side_by_side;
        }
        let groups: Vec<usize> = tab.panes.iter().map(|p| p.group).collect();
        let (at, group) =
            idecraft_terminal::split_position(&groups, tab.active, tab.side_by_side, side_by_side);
        pane.group = group;
        tab.active = at;
        tab.panes.insert(at, pane);
        self.focus_terminal(window, cx);
        self.save_terminals(cx);
        cx.notify();
    }

    /// Focuses the next or previous shell of the tab shown (`Terminal.NextSplitter`,
    /// `Terminal.PrevSplitter`, ⌥⌘→/⌥⌘←).
    pub fn focus_terminal_sibling(
        &mut self,
        forward: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(tab) = self.terminals.get_mut(self.terminal_tab) else {
            return;
        };
        let n = tab.panes.len();
        tab.active = if forward {
            (tab.active + 1) % n
        } else {
            (tab.active + n - 1) % n
        };
        self.focus_terminal(window, cx);
        cx.notify();
    }

    /// Closes the shell `view` (⌘W or its program ended; SPEC-0205 behaviours 4 and 5): its tab
    /// closes with its last shell.
    fn close_terminal_view(
        &mut self,
        view: &Entity<TerminalView>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some((i, j)) = self.locate_terminal(view) else {
            return;
        };
        if self.terminals[i].panes.len() == 1 {
            self.close_terminal_tab(i, window, cx);
            return;
        }
        let tab = &mut self.terminals[i];
        tab.panes.remove(j);
        if j < tab.active || tab.active >= tab.panes.len() {
            tab.active = tab.active.saturating_sub(1);
        }
        if i == self.terminal_tab {
            self.focus_terminal(window, cx);
        }
        self.save_terminals(cx);
        cx.notify();
    }

    /// Shows terminal tab `i`.
    pub fn select_terminal_tab(&mut self, i: usize, window: &mut Window, cx: &mut Context<Self>) {
        if i < self.terminals.len() {
            self.terminal_tab = i;
            self.focus_terminal(window, cx);
            cx.notify();
        }
    }

    /// Closes terminal tab `i` and ends its shells; the window hides with the last tab (× on the
    /// tab, ⌘W on its last shell; SPEC-0205 behaviour 4).
    pub fn close_terminal_tab(&mut self, i: usize, window: &mut Window, cx: &mut Context<Self>) {
        if i >= self.terminals.len() {
            return;
        }
        // Dropping the tab drops its subscriptions and ends its shells.
        self.terminals.remove(i);
        self.terminal_rename = None;
        if self.terminals.is_empty() {
            self.terminal_tab = 0;
            self.show_terminal = false;
            self.focus_active(window, cx);
        } else {
            self.terminal_tab = self.terminal_tab.min(self.terminals.len() - 1);
            if i < self.terminal_tab {
                self.terminal_tab -= 1;
            }
            self.focus_terminal(window, cx);
        }
        self.save_terminals(cx);
        cx.notify();
    }

    /// Turns the name of tab `i` into a field with the name selected (double click,
    /// `Terminal.RenameSession`; SPEC-0205 behaviour 2).
    pub fn start_terminal_rename(&mut self, i: usize, window: &mut Window, cx: &mut Context<Self>) {
        let Some(tab) = self.terminals.get(i) else {
            return;
        };
        let name = tab.name.clone();
        let field = cx.new(EditorView::field);
        field.update(cx, |f, cx| {
            f.set_text_selected(&name, cx);
        });
        let focus = field.read(cx).focus();
        window.focus(&focus);
        // Leaving the field cancels.
        let blur = cx.on_blur(&focus, window, |this, _, cx| {
            this.terminal_rename = None;
            cx.notify();
        });
        self.terminal_rename = Some((i, field, blur));
        cx.notify();
    }

    /// Ends the rename: Enter keeps a non-empty name, Escape cancels.
    fn finish_terminal_rename(&mut self, keep: bool, window: &mut Window, cx: &mut Context<Self>) {
        let Some((i, field, _blur)) = self.terminal_rename.take() else {
            return;
        };
        if keep {
            let name = field.read(cx).state.buffer.text();
            self.rename_terminal_tab(i, &name, cx);
        }
        self.focus_terminal(window, cx);
        cx.notify();
    }

    /// Renames tab `i`; an empty name keeps the old one.
    pub fn rename_terminal_tab(&mut self, i: usize, name: &str, cx: &mut Context<Self>) {
        let name = name.trim();
        if let Some(tab) = self.terminals.get_mut(i)
            && !name.is_empty()
        {
            tab.name = name.to_owned();
            self.save_terminals(cx);
            cx.notify();
        }
    }

    /// The field editing a tab's name, while it is shown (for tests).
    pub fn terminal_rename_field(&self) -> Option<Entity<EditorView>> {
        self.terminal_rename.as_ref().map(|(_, f, _)| f.clone())
    }

    /// The tabs as saved: names, splits and per shell its folder and last lines; SSH terminals are
    /// left out (SPEC-0205 behaviour 6).
    pub fn saved_terminals(&self, cx: &gpui::App) -> idecraft_terminal::SavedTerminals {
        idecraft_terminal::SavedTerminals {
            tabs: self
                .terminals
                .iter()
                .filter_map(|t| {
                    let shells: Vec<_> = t
                        .panes
                        .iter()
                        .map(|p| (p.view.read(cx), p.group))
                        .filter(|(v, _)| v.is_local())
                        .map(|(v, group)| idecraft_terminal::SavedShell {
                            group: Some(group),
                            ..idecraft_terminal::SavedShell::new(
                                v.current_dir(),
                                v.history_lines(idecraft_terminal::SAVED_LINES),
                            )
                        })
                        .collect();
                    (!shells.is_empty()).then(|| idecraft_terminal::SavedTab {
                        name: t.name.clone(),
                        side_by_side: t.side_by_side,
                        shells,
                    })
                })
                .collect(),
        }
    }

    /// Writes the tabs to `.idecraft/terminal-sessions.json`; before the saved ones came back
    /// they stay untouched.
    fn save_terminals(&self, cx: &gpui::App) {
        self.sync_terminal_labels(cx);
        // Host terminals live with their session; their text is not written here.
        if self.terminals_restored && self.remote_project.is_none() {
            let saved = self.saved_terminals(cx);
            // The shells' last lines are state of one user and may hold secrets: the generated
            // ignore file lists them before they are written (`SPEC-0069` behaviour 3a).
            if !saved.tabs.is_empty() {
                idecraft_core::local_state::refresh_local_state_ignore(&self.root);
            }
            let _ = saved.save(&self.root);
        }
    }

    /// Starts the saved tabs again as when the project opens (for the self-test).
    pub fn reload_saved_terminals(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.terminals_restored = false;
        if self.restore_terminals(window, cx) {
            self.show_terminal = true;
            self.focus_terminal(window, cx);
        }
        cx.notify();
    }

    /// Starts the saved tabs with their names, splits, folders and lines; false when there are
    /// none (SPEC-0205 behaviour 6).
    pub fn restore_terminals(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if self.terminals_restored {
            return false;
        }
        self.terminals_restored = true;
        let saved = idecraft_terminal::SavedTerminals::load(&self.root);
        for tab in saved.tabs.into_iter().filter(|t| !t.shells.is_empty()) {
            let panes = tab
                .shells
                .into_iter()
                .enumerate()
                .map(|(i, shell)| {
                    let cwd = shell.start_dir(&self.root);
                    let group = shell.group.unwrap_or(i);
                    let view = cx.new(|cx| TerminalView::new(cwd, cx).with_history(shell.lines));
                    TerminalPane {
                        group,
                        ..self.terminal_pane(view, window, cx)
                    }
                })
                .collect();
            self.terminals.push(TerminalTab {
                name: tab.name,
                panes,
                side_by_side: tab.side_by_side,
                active: 0,
            });
        }
        self.terminal_tab = 0;
        !self.terminals.is_empty()
    }

    /// The Commit tool window, if it was opened.
    pub fn commit_view(&self) -> Option<Entity<CommitView>> {
        self.commit.clone()
    }

    /// Shows the Commit tool window in place of the project tree and focuses its message, or goes
    /// back to the tree (`ActivateCommitToolWindow`, SPEC-0063 behaviour 6).
    fn toggle_commit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.show_commit {
            self.show_commit = false;
            self.focus_active(window, cx);
        } else {
            let root = self.root.clone();
            if self.commit.is_none() {
                let view = cx.new(|cx| CommitView::new(&root, cx));
                if let Some(host) = self.remote_host_call() {
                    view.update(cx, |v, cx| v.set_remote(host, cx));
                }
                self._commit_events = Some(cx.subscribe_in(
                    &view,
                    window,
                    |this, _, event: &CommitEvent, window, cx| match event {
                        CommitEvent::ShowDiff(path) => {
                            let path = path.clone();
                            this.show_diff(&path, window, cx);
                        }
                        CommitEvent::OpenFile(path) => {
                            let file = idecraft_vcs::Repo::discover(&this.root)
                                .ok()
                                .and_then(|r| r.workdir().map(|w| w.join(path)));
                            if let Some(file) = file {
                                this.open(&file, window, cx);
                                this.focus_active(window, cx);
                            }
                        }
                        CommitEvent::Commit if this.remote_project.is_some() => {
                            // The remote documents are saved on the host first (SPEC-0318 v2
                            // detail 7).
                            this.remote_save_all_now(cx);
                            if let Some(commit) = this.commit.clone() {
                                commit.update(cx, |c, cx| c.commit_now(cx));
                            }
                        }
                        CommitEvent::Commit => {
                            // The commit takes what the editors show (SPEC-0063 v3 behaviour 7).
                            for editor in this.editors.values() {
                                editor.update(cx, |e, cx| {
                                    if e.state.buffer.is_modified() {
                                        e.run_action("SaveDocument", cx);
                                    }
                                });
                            }
                            if let Some(commit) = this.commit.clone() {
                                commit.update(cx, |c, cx| c.commit_now(cx));
                            }
                        }
                        CommitEvent::Push => {
                            // Commit and Push… (SPEC-0063 v5 behaviour 15).
                            this.refresh_branch();
                            this.reload_git_log(cx);
                            this.refresh_annotations(None, cx);
                            this.open_push(window, cx);
                        }
                        CommitEvent::RolledBack(paths) => {
                            // Open editors show what the rollback wrote (v5 behaviour 10).
                            for path in paths {
                                if let Some(editor) = this.editors.get(path) {
                                    editor.update(cx, |e, cx| e.reload_from_disk(cx));
                                }
                            }
                            this.refresh_annotations(None, cx);
                            cx.notify();
                        }
                        CommitEvent::Status(text) => {
                            this.status = Some(text.clone());
                            cx.notify();
                        }
                        CommitEvent::Committed(text) => {
                            this.status = Some(text.clone());
                            this.refresh_branch();
                            this.reload_git_log(cx);
                            // Annotations follow the new HEAD (SPEC-0277 behaviour 8).
                            this.refresh_annotations(None, cx);
                            cx.notify();
                        }
                    },
                ));
                self.commit = Some(view);
            }
            let view = self.commit.clone().expect("just created");
            let unsaved = self.unsaved_in_repo(cx);
            view.update(cx, |v, _| {
                v.set_unsaved(unsaved);
                v.refresh();
            });
            self.show_commit = true;
            window.focus(&view.read(cx).focus(cx));
        }
        cx.notify();
    }

    /// Files with unsaved changes in open editors, relative to the repository root.
    fn unsaved_in_repo(&self, cx: &gpui::App) -> Vec<String> {
        // A remote project's unsaved documents, by their path in the project (the host lists
        // its status with project-relative paths, SPEC-0318 behaviour 3).
        if self.remote_project.is_some() {
            return self
                .editors
                .iter()
                .filter(|(p, e)| e.read(cx).is_modified() || self.remote_unsaved(p))
                .filter_map(|(p, _)| self.remote_rel(p))
                .collect();
        }
        let Some(workdir) = idecraft_vcs::Repo::discover(&self.root)
            .ok()
            .and_then(|r| r.workdir().map(Path::to_path_buf))
        else {
            return Vec::new();
        };
        let workdir = workdir.canonicalize().unwrap_or(workdir);
        self.editors
            .iter()
            .filter(|(_, e)| e.read(cx).state.buffer.is_modified())
            .filter_map(|(p, _)| {
                p.strip_prefix(&workdir)
                    .ok()
                    .map(|r| r.to_string_lossy().replace('\\', "/"))
            })
            .collect()
    }

    /// Shows `path` (relative to the repository root) at HEAD and in the working copy side by side
    /// over the editor area; the working copy is the open editor's text when the file is open
    /// (SPEC-0084 behaviour 2).
    pub fn show_diff(&mut self, path: &str, window: &mut Window, cx: &mut Context<Self>) {
        let repo = match idecraft_vcs::Repo::discover(&self.root) {
            Ok(r) => r,
            Err(e) => {
                self.status = Some(e.to_string());
                cx.notify();
                return;
            }
        };
        let Some(workdir) = repo.workdir().map(Path::to_path_buf) else {
            return;
        };
        let file = workdir.join(path);
        let old = match repo.head_text(path) {
            Ok(t) => t.unwrap_or_default(),
            Err(e) => {
                self.status = Some(e.to_string());
                cx.notify();
                return;
            }
        };
        let open = file
            .canonicalize()
            .ok()
            .and_then(|f| self.editors.get(&f))
            .map(|e| e.read(cx).state.buffer.text());
        let new: String = open
            .or_else(|| std::fs::read_to_string(&file).ok())
            .unwrap_or_default();
        let rows = idecraft_vcs::side_by_side(&old, &new);
        let unified = self.diff_unified;
        let view = cx.new(|cx| {
            DiffView::new(path.to_owned(), rows, cx)
                .with_texts(&file, &old, &new)
                .with_unified(unified)
                .revertible()
        });
        self.present_diff(view, window, cx);
        self.diff_sides = Some(crate::diff_actions::Sides {
            left: crate::diff_actions::Side::Fixed(old),
            right: crate::diff_actions::Side::File(file.clone()),
        });
        self.diff_file = Some((path.to_owned(), file));
    }

    /// Shows `view` as the diff viewer with its tab (`SPEC-0084` v2 behaviour 6); Escape returns
    /// to the Commit tool window when it is shown, else to the editor.
    fn present_diff(
        &mut self,
        view: Entity<DiffView>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self._diff_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &DiffEvent, window, cx| match event {
                DiffEvent::Unified(u) => {
                    this.diff_unified = *u;
                    this.diff_asked = None;
                }
                DiffEvent::Revert(change) => {
                    this.take_diff_side(true, Some(change.clone()), cx);
                }
                DiffEvent::Stepped { forward, moved } => {
                    this.diff_stepped(*forward, *moved, window, cx);
                }
                DiffEvent::Close => {
                    this.diff = None;
                    this.diff_file = None;
                    this.diff_sides = None;
                    this.diff_asked = None;
                    match this.commit.clone().filter(|_| this.show_commit) {
                        Some(commit) => window.focus(&commit.read(cx).focus(cx)),
                        None => this.focus_active(window, cx),
                    }
                    cx.notify();
                }
            },
        ));
        let unified = self.diff_unified;
        view.update(cx, |v, _| v.set_unified(unified));
        self.diff_file = None;
        self.diff_sides = None;
        self.diff_asked = None;
        window.focus(&view.read(cx).focus());
        self.diff = Some(view);
        cx.notify();
    }

    /// Reads `.idecraft/run.toml` again; the selection stays if the configuration still exists,
    /// else the first one is selected (SPEC-0087 behaviour 1).
    fn reload_run_configs(&mut self) {
        // A remote project's configurations are the host's (SPEC-0318 v2 detail 3).
        if self.remote_project.is_some() {
            self.remote_take_run_configs(true);
            return;
        }
        (self.run_configs, self.run_detected) = all_run_configs(&self.root);
        // The Before Run tasks of the build tools window go first (SPEC-0100 v3 behaviour 18);
        // the window's own temporary task runs below do not get them.
        let mut configs = std::mem::take(&mut self.run_configs.configs);
        self.add_before_run_tasks(&mut configs);
        self.run_configs.configs = configs;
        for t in &self.run_temporary {
            if !self.run_configs.configs.iter().any(|c| c.name == t.name) {
                self.run_configs.configs.push(t.clone());
            }
        }
        // Then what plugins suggest, for those the user granted it (SPEC-0276 behaviour 4).
        let active = self.active_path().and_then(|p| {
            p.strip_prefix(&self.root)
                .ok()
                .map(|r| r.to_string_lossy().replace('\\', "/"))
        });
        let types = idecraft_plugins::run_types(
            &self.plugins,
            self.plugins_dir.as_deref(),
            &self.root,
            active,
        );
        let allowances = self
            .plugin_run_file
            .as_deref()
            .map(|f| idecraft_plugins::load_allowances(f, &self.root))
            .unwrap_or_default();
        self.run_plugin.clear();
        for (t, entry) in types
            .iter()
            .flat_map(|t| t.commands.iter().map(move |c| (t, c)))
            .zip(crate::plugin_run_model::entries(&types, &allowances))
        {
            let (t, command) = t;
            if !self
                .run_configs
                .configs
                .iter()
                .any(|c| c.name == entry.config_name)
            {
                self.run_configs.configs.push(t.run_config(command));
                self.run_plugin.push(entry);
            }
        }
        let keep = self
            .run_selected
            .as_ref()
            .is_some_and(|n| self.run_configs.configs.iter().any(|c| &c.name == n));
        // "Current File" chosen in the run widget stays chosen (SPEC-0087 v6 behaviour 9).
        if self.run_current_file {
            self.run_selected = None;
        } else if !keep {
            self.run_selected = self.run_configs.configs.first().map(|c| c.name.clone());
        }
    }

    /// Why nothing can run, if so (behaviour 1).
    fn run_problem(&self) -> Option<String> {
        if let Some(p) = self.run_configs.problems.first() {
            return Some(format!("Run configurations: {p}"));
        }
        if self.run_configs.configs.is_empty() {
            return Some(format!(
                "No run configurations: add [[run]] entries to {}",
                idecraft_core::RUN_FILE
            ));
        }
        None
    }

    fn ensure_run_view(&mut self, window: &mut Window, cx: &mut Context<Self>) -> Entity<RunView> {
        if let Some(v) = &self.run_view {
            return v.clone();
        }
        let root = self.root.clone();
        let view = cx.new(|cx| RunView::new(&root, cx));
        self._run_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &RunViewEvent, window, cx| match event {
                RunViewEvent::Hide => {
                    this.show_run = false;
                    this.focus_active(window, cx);
                    cx.notify();
                }
                RunViewEvent::ContextMenu(at) => {
                    this.open_context_menu(MenuPlace::Run, None, *at, cx)
                }
                // SPEC-0087 v6 behaviour 12: Rerun stops a run that still goes first.
                RunViewEvent::Rerun(name) => {
                    this.reload_run_configs();
                    if this.run_configs.configs.iter().any(|c| &c.name == name) {
                        this.run_selected = Some(name.clone());
                        this.run_current_file = false;
                        // The tab's own run is the one to stop: no question, no further
                        // instance (SPEC-0047 v3 behaviour 10).
                        let title = this
                            .run_view
                            .as_ref()
                            .and_then(|v| v.read(cx).selected_title())
                            .unwrap_or_else(|| name.clone());
                        this.start_run_in(name, RunStart::InTab(title), window, cx);
                    } else {
                        this.status = Some(crate::run_model::cannot_start(
                            name,
                            "the configuration no longer exists",
                        ));
                        cx.notify();
                    }
                }
                RunViewEvent::OpenConfiguration(name) => {
                    this.open_run_config_editor(Some(name.clone()), window, cx)
                }
                // SPEC-0088 v5 behaviour 12: a test's source, the editor focused.
                RunViewEvent::OpenSource(path, line) => {
                    this.open_at_line(path, *line, window, cx);
                    this.focus_active(window, cx);
                }
                RunViewEvent::Status(text) => {
                    this.status = Some(text.clone());
                    cx.notify();
                }
                // SPEC-0088 v3 behaviour 7: only the tests that failed run again.
                RunViewEvent::RerunFailed(name, report) => {
                    this.reload_run_configs();
                    let config = this
                        .run_configs
                        .configs
                        .iter()
                        .find(|c| &c.name == name)
                        .cloned();
                    match config.map(|c| idecraft_core::rerun_failed(&c, report)) {
                        Some(Ok(again)) => this.run_temporary_config(again, window, cx),
                        Some(Err(why)) => {
                            this.status = Some(crate::run_model::cannot_start(name, &why));
                            cx.notify();
                        }
                        None => {
                            this.status = Some(crate::run_model::cannot_start(
                                name,
                                "the configuration no longer exists",
                            ));
                            cx.notify();
                        }
                    }
                }
            },
        ));
        self.run_view = Some(view.clone());
        view
    }

    /// Runs the selected configuration (`Run`, SPEC-0087 behaviour 3); the editor keeps the focus.
    pub fn run_selected(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.reload_run_configs();
        if let Some(problem) = self.run_problem() {
            self.status = Some(problem);
            cx.notify();
            return;
        }
        let Some(name) = self.run_selected.clone() else {
            return;
        };
        // A command suggested by a plugin starts only after the user confirms it, unless they
        // always allow exactly this command here (SPEC-0276 behaviours 5 and 7).
        if let Some(entry) = self.plugin_run_entry(&name)
            && !entry.always_allowed
        {
            self.confirm_plugin_run(entry, window, cx);
            return;
        }
        self.start_run_named(&name, window, cx);
    }

    /// Writes the modified documents before something is started (SPEC-0087 v5 behaviour 3a): what
    /// runs reads the files, not the editors. False, with the reason in the status bar, when a
    /// document could not be saved; then nothing is started.
    pub(super) fn save_before_launch(&mut self, cx: &mut Context<Self>) -> bool {
        let folders = self.remote_folders();
        let mut left: Vec<String> = self
            .save_all_editors(cx)
            .iter()
            .map(|p| chrome::shown_path(p, None, folders.as_ref()))
            .collect();
        left.extend(self.remote_unsaved_names(cx));
        match crate::run_model::unsaved_refusal(&left) {
            Some(refusal) => {
                self.status = Some(refusal);
                cx.notify();
                false
            }
            None => true,
        }
    }

    /// Why configuration `name` cannot start here, if it cannot (`SPEC-0087` v6 behaviour 14).
    fn run_blocker(&self, name: &str) -> Option<String> {
        let c = self.run_configs.configs.iter().find(|c| c.name == name)?;
        let problems: Vec<String> = if self.run_temporary.iter().any(|t| t.name == name)
            || self.run_detected.iter().any(|d| d == name)
        {
            Vec::new()
        } else {
            self.run_configs.problems.clone()
        };
        idecraft_core::start_blocker(&self.root, c, &problems)
    }

    /// Why each configuration cannot start, for the warning signs of the list (v6 behaviour 14).
    fn run_blockers(&self) -> HashMap<String, String> {
        if self.remote_project.is_some() {
            return HashMap::new();
        }
        self.run_configs
            .configs
            .iter()
            .filter_map(|c| self.run_blocker(&c.name).map(|why| (c.name.clone(), why)))
            .collect()
    }

    /// Shows why configuration `name` cannot start: in the status bar and in its Run tab
    /// (`SPEC-0087` v6 behaviour 14, IMP-0394).
    fn refuse_run(
        &mut self,
        name: &str,
        reason: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.status = Some(crate::run_model::cannot_start(name, reason));
        let view = self.ensure_run_view(window, cx);
        view.update(cx, |v, cx| v.refuse(name, reason, cx));
        self.show_run = true;
        cx.notify();
    }

    /// Starts configuration `name` in the Run tool window. While it runs already, a configuration
    /// that allows one instance asks first (Stop and Rerun, Cancel) and one that allows several
    /// starts a further instance in a tab of its own (`SPEC-0047` v3 behaviour 10).
    fn start_run_named(&mut self, name: &str, window: &mut Window, cx: &mut Context<Self>) {
        self.start_run_in(name, RunStart::ByRule, window, cx);
    }

    /// Starts configuration `name` as `how` says.
    fn start_run_in(
        &mut self,
        name: &str,
        how: RunStart,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        // The instance rule, for runs on this machine (a remote project's host keeps one run
        // per configuration).
        let mut how = how;
        if how == RunStart::ByRule && self.remote_project.is_none() {
            let running = self
                .run_view
                .as_ref()
                .map_or(0, |v| v.read(cx).running_instances(name));
            let rule = self
                .run_configs
                .configs
                .iter()
                .find(|c| c.name == name)
                .map(|c| idecraft_core::second_start(c, running));
            match rule {
                Some(idecraft_core::SecondStart::Ask) => {
                    let (message, detail, answers) = idecraft_core::second_start_question(name);
                    self.drawn_question = Some((
                        crate::dialogs::DrawnQuestion {
                            message,
                            detail,
                            buttons: answers.iter().map(|a| (*a).to_owned()).collect(),
                            default: 0,
                            cancel: Some(1),
                        },
                        DrawnFor::RerunRunning(name.to_owned()),
                    ));
                    self.show_run = true;
                    cx.notify();
                    return;
                }
                Some(idecraft_core::SecondStart::NewInstance) => how = RunStart::NewInstance,
                _ => {}
            }
        }
        if self.remote_project.is_none()
            && let Some(reason) = self.run_blocker(name)
        {
            self.refuse_run(name, &reason, window, cx);
            return;
        }
        if !self.save_before_launch(cx) {
            return;
        }
        if self.remote_project.is_some() {
            self.remote_start_run(
                idecraft_remote::RunTarget::Name(name.to_owned()),
                window,
                cx,
            );
            return;
        }
        let view = self.ensure_run_view(window, cx);
        let configs = self.run_configs.clone();
        let started = view.update(cx, |v, cx| match &how {
            RunStart::NewInstance => v.run_instance(&configs, name, cx).map(|_| ()),
            RunStart::InTab(title) => v.run_in_tab(&configs, name, title, cx),
            RunStart::ByRule | RunStart::Replace => v.run(&configs, name, cx),
        });
        if let Err(e) = started {
            view.update(cx, |v, cx| v.refuse(name, &e, cx));
            self.status = Some(crate::run_model::cannot_start(name, &e));
        } else if let Some(page) = configs
            .configs
            .iter()
            .find(|c| c.name == name)
            .and_then(|c| {
                let key = if cfg!(target_os = "macos") {
                    "⌃D"
                } else {
                    "⇧F9"
                };
                crate::run_model::page_run_status(c, key)
            })
        {
            // SPEC-0133 v2 behaviour 1 (hand test 60).
            self.status = Some(page);
        }
        self.show_run = true;
        cx.notify();
    }

    /// The plugin suggestion behind run configuration `name`, if it is one (SPEC-0276).
    fn plugin_run_entry(&self, name: &str) -> Option<crate::plugin_run_model::PluginRunEntry> {
        self.run_plugin
            .iter()
            .find(|e| e.config_name == name)
            .cloned()
    }

    /// Shows the confirmation for the plugin suggestion `entry` (SPEC-0276 behaviour 5).
    fn confirm_plugin_run(
        &mut self,
        entry: crate::plugin_run_model::PluginRunEntry,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let root = self.root.clone();
        let dialog = cx.new(|cx| crate::PluginRunDialog::new(entry, &root, cx));
        self._plugin_run_dialog_events = Some(cx.subscribe_in(
            &dialog,
            window,
            |this, dialog, event: &crate::PluginRunDialogEvent, window, cx| {
                let crate::PluginRunDialogEvent::Chosen(choice) = *event;
                let entry = dialog.read(cx).entry().clone();
                this.plugin_run_dialog = None;
                this.focus_active(window, cx);
                this.plugin_run_chosen(&entry, choice, window, cx);
                cx.notify();
            },
        ));
        window.focus(&dialog.read(cx).focus());
        self.plugin_run_dialog = Some(dialog);
        cx.notify();
    }

    /// Carries out the choice of the confirmation (SPEC-0276 behaviours 5–7).
    fn plugin_run_chosen(
        &mut self,
        entry: &crate::plugin_run_model::PluginRunEntry,
        choice: crate::plugin_run_model::ConfirmChoice,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        use crate::plugin_run_model::ConfirmChoice;
        match choice {
            ConfirmChoice::Cancel => {
                self.status = Some(format!("Not started: {}", entry.config_name));
            }
            ConfirmChoice::RunOnce => self.start_run_named(&entry.config_name, window, cx),
            ConfirmChoice::AlwaysAllow => {
                let stored = match self.plugin_run_file.as_deref() {
                    Some(file) => idecraft_plugins::allow(file, &self.root, &entry.allowance),
                    None => Err("no settings folder".into()),
                };
                if let Some(e) = self
                    .run_plugin
                    .iter_mut()
                    .find(|e| e.config_name == entry.config_name)
                {
                    e.always_allowed = stored.is_ok();
                }
                self.start_run_named(&entry.config_name, window, cx);
                if let Err(e) = stored {
                    self.status = Some(format!("Started once; could not keep the permission: {e}"));
                }
            }
        }
        cx.notify();
    }

    /// The confirmation before a plugin's command starts, if it is open (SPEC-0276).
    pub fn plugin_run_dialog(&self) -> Option<Entity<crate::PluginRunDialog>> {
        self.plugin_run_dialog.clone()
    }

    /// Forgets "always allow" of the plugin suggestion `name` in this workspace (SPEC-0276
    /// behaviour 8).
    fn revoke_plugin_run(&mut self, name: &str) {
        let Some(entry) = self.plugin_run_entry(name) else {
            return;
        };
        let a = &entry.allowance;
        let result = match self.plugin_run_file.as_deref() {
            Some(file) => {
                idecraft_plugins::revoke(file, &self.root, &a.plugin, Some(&a.kind), Some(&a.name))
            }
            None => Ok(0),
        };
        self.status = Some(match result {
            Ok(_) => format!("{name} will ask again before it starts"),
            Err(e) => format!("Could not revoke: {e}"),
        });
        for e in self.run_plugin.iter_mut().filter(|e| e.config_name == name) {
            e.always_allowed = false;
        }
    }

    /// Runs or debugs the file in the editor (`RunClass` ⌃⇧R, `DebugClass` ⌃⇧D; SPEC-0097
    /// behaviours 3–4): a configuration named after the class or file is made for the session,
    /// selected and started.
    fn run_context(&mut self, debug: bool, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if self.remote_project.is_some() {
            return self.remote_run_context(debug, window, cx);
        }
        let Some(editor) = self.active_editor() else {
            return false;
        };
        let Some(path) = self.active_path() else {
            return false;
        };
        let Ok(rel) = path.strip_prefix(&self.root) else {
            return false;
        };
        let rel = rel.to_string_lossy().replace('\\', "/");
        let text = editor.read(cx).state.buffer.text();
        // Inside a test method only that method runs (SPEC-0122 behaviour 1).
        if !debug
            && let Some(lang) = idecraft_languages::jvm::Jvm::of(&rel)
            && let Some((line, _)) = self.caret_position(cx)
            && let Some(marker) =
                idecraft_languages::jvm::test_method_at(lang, &text, line.saturating_sub(1))
            && let Some(method) = marker.method.as_deref()
            && let Some(config) =
                idecraft_core::test_method_config(&self.project_model(), &rel, &text, method)
        {
            self.run_temporary_config(config, window, cx);
            return true;
        }
        let model = idecraft_core::Workspace::open(&self.root)
            .ok()
            .and_then(|w| w.files().ok())
            .map(|files| idecraft_core::read_project(&self.root, &files))
            .unwrap_or_default();
        // Inside a test or suite of Vitest or Jest only that one runs (SPEC-0045 v4 behaviour 12).
        if !debug
            && let Some((line, _)) = self.caret_position(cx)
            && let Some(marker) =
                idecraft_languages::js_tests::marker_at(&rel, &text, line.saturating_sub(1))
            && let Some(config) = idecraft_core::js_test_config(
                &model,
                &rel,
                &text,
                &marker.class,
                marker.kind == idecraft_languages::jvm::MarkerKind::TestClass,
            )
        {
            self.run_temporary_config(config, window, cx);
            return true;
        }
        // Inside a test of pytest, Go or Rust only that test runs; a pytest class runs its tests
        // (SPEC-0045 v5 behaviour 13, OBS-0034 R1).
        if !debug
            && let Some((line, _)) = self.caret_position(cx)
            && let Some(marker) =
                idecraft_languages::test_markers::marker_at(&rel, &text, line.saturating_sub(1))
            && let Some(config) = idecraft_core::single_test_config(
                &model,
                &rel,
                &text,
                &marker.class,
                marker.method.as_deref(),
            )
        {
            self.run_temporary_config(config, window, cx);
            return true;
        }
        // An HTML page opens in the browser; Debug opens it in Chrome (SPEC-0133 behaviour 3).
        let page =
            (rel.ends_with(".html") || rel.ends_with(".htm")).then(|| idecraft_core::RunConfig {
                name: path
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default(),
                command: Vec::new(),
                cwd: std::path::Path::new(&rel)
                    .parent()
                    .map(|p| p.to_string_lossy().into_owned())
                    .filter(|p| !p.is_empty()),
                env: Default::default(),
                kind: idecraft_core::RunKind::Run,
                report: None,
                report_file: None,
                before: Vec::new(),
                timeout: None,
                url: Some(format!("file://{}", path.display())),
                folder: None,
                allow_multiple: false,
                before_launch: Vec::new(),
                verbatim: false,
            });
        let Some(config) = page.or_else(|| idecraft_core::context_config(&model, &rel, &text))
        else {
            self.status = Some("Nothing to run in this file".into());
            cx.notify();
            return true;
        };
        if debug {
            let name = config.name.clone();
            self.push_temporary(config);
            self.run_selected = Some(name);
            self.run_current_file = false;
            self.debug_selected(window, cx);
        } else {
            self.run_temporary_config(config, window, cx);
        }
        true
    }

    /// Whether the active file offers something to run, as the editor's Run would find it
    /// (SPEC-0061 v17 behaviour 66): no editor or a file outside the project offers nothing, an
    /// HTML page opens in the browser; a remote project's host decides, so it counts as runnable.
    pub fn current_file_runnable(&self, cx: &gpui::App) -> bool {
        if self.remote_project.is_some() {
            return true;
        }
        let (Some(editor), Some(path)) = (self.active_editor(), self.active_path()) else {
            return false;
        };
        let Ok(rel) = path.strip_prefix(&self.root) else {
            return false;
        };
        let rel = rel.to_string_lossy().replace('\\', "/");
        let revision = editor.read(cx).revision();
        let mut cache = self.run_file.borrow_mut();
        if let Some(f) = cache.as_ref()
            && f.path == path
            && f.revision == revision
        {
            return f.runnable;
        }
        let model = match cache.take() {
            Some(f) if f.path == path => f.model,
            _ => self.project_model(),
        };
        let text = editor.read(cx).state.buffer.text();
        let runnable = rel.ends_with(".html")
            || rel.ends_with(".htm")
            || idecraft_core::context_config(&model, &rel, &text).is_some();
        *cache = Some(RunFile {
            path,
            revision,
            model,
            runnable,
        });
        runnable
    }

    /// Whether the toolbar's Run and Debug can act: a configuration is chosen, or "Current File"
    /// offers something to run (SPEC-0061 v17 behaviour 66).
    pub fn run_buttons_enabled(&self, cx: &gpui::App) -> bool {
        self.run_selected.is_some() || self.current_file_runnable(cx)
    }

    /// Stops the run shown in the Run tool window (`Stop`, behaviour 5).
    pub fn stop_run(&mut self, cx: &mut Context<Self>) {
        if let Some(v) = &self.run_view {
            v.update(cx, |v, cx| {
                v.stop_selected();
                cx.notify();
            });
        }
    }

    /// Problems of the active file, or of all open files (SPEC-0092 behaviour 2).
    pub fn problems_list(&self, cx: &gpui::App) -> Vec<crate::problems_model::Located> {
        match self.problems_scope {
            crate::problems_model::Scope::File => self
                .active_path()
                .as_ref()
                .and_then(|p| self.editors.get(p).map(|e| e.read(cx).located_problems(p)))
                .unwrap_or_default(),
            // Errors of the open files and those the servers published for other files
            // (SPEC-0092 v3 behaviour 7).
            crate::problems_model::Scope::Project => self
                .editors
                .iter()
                .flat_map(|(p, e)| e.read(cx).located_problems(p))
                .chain(
                    self.pool_pending
                        .iter()
                        .filter(|(path, _)| !self.editors.contains_key(*path))
                        .flat_map(|(path, found)| {
                            found
                                .iter()
                                .filter(|d| crate::problem_marks::lsp_error(&d.severity))
                                .map(|d| crate::problems_model::Located {
                                    path: path.clone(),
                                    line: d.start_line as usize,
                                    column: d.start_character as usize,
                                    offset: 0,
                                    severity: crate::diagnostics_model::Severity::Error,
                                    message: match &d.source {
                                        Some(s) => format!("{s}: {}", d.message),
                                        None => d.message.clone(),
                                    },
                                    inspection: None,
                                })
                        }),
                )
                .filter(|p| p.severity == crate::diagnostics_model::Severity::Error)
                .collect(),
            crate::problems_model::Scope::Inspection => self.inspection.clone(),
        }
    }

    /// Compares the clipboard with the selection, or the whole file without one, in the diff view
    /// (SPEC-0275 v6 behaviour 14b).
    pub fn compare_with_clipboard(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(editor) = self.active_editor() else {
            return;
        };
        let (text, selected) = {
            let e = editor.read(cx);
            match e.selection_range() {
                Some(r) => (e.state.buffer.slice(r).unwrap_or_default(), true),
                None => (e.state.buffer.text(), false),
            }
        };
        let clipboard = cx.read_from_clipboard().and_then(|c| c.text());
        let Some(rows) = crate::context_menu::clipboard_comparison(clipboard.as_deref(), &text)
        else {
            self.status = Some("The clipboard holds no text to compare".into());
            cx.notify();
            return;
        };
        let name = self
            .active_path()
            .and_then(|p| p.file_name().map(|n| n.to_string_lossy().into_owned()))
            .unwrap_or_default();
        let right = if selected {
            format!("{name} (selection)")
        } else {
            name.clone()
        };
        let view = cx.new(|cx| {
            DiffView::new(format!("Clipboard vs {right}"), rows, cx).with_sides("Clipboard", &right)
        });
        self._diff_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &DiffEvent, window, cx| match event {
                DiffEvent::Unified(u) => this.diff_unified = *u,
                DiffEvent::Revert(_) | DiffEvent::Stepped { .. } => {}
                DiffEvent::Close => {
                    this.diff = None;
                    this.focus_active(window, cx);
                    cx.notify();
                }
            },
        ));
        let unified = self.diff_unified;
        view.update(cx, |v, _| v.set_unified(unified));
        self.diff_file = None;
        self.diff_sides = None;
        self.diff_asked = None;
        window.focus(&view.read(cx).focus());
        self.diff = Some(view);
        cx.notify();
    }

    /// Runs IDECraft's inspections over every project file in the background and lists the results
    /// in the Problems tool window's Inspection tab (`InspectCode`, SPEC-0098 behaviour 4).
    pub fn inspect_code(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        // First the scope dialog (SPEC-0098 v3 behaviour 7), for every inspection.
        self.inspect_only = None;
        let choices = crate::problems_model::InspectScope::choices(self.active_path().as_deref());
        self.inspect_dialog = Some((choices, 0));
        window.focus(&self.inspect_dialog_focus);
        cx.notify();
    }

    /// The scope dialog of Inspect Code, if it is open: its choices as labels and the chosen one.
    pub fn inspect_dialog(&self) -> Option<(Vec<String>, usize)> {
        self.inspect_dialog
            .as_ref()
            .map(|(choices, at)| (choices.iter().map(|c| c.label(&self.root)).collect(), *at))
    }

    fn on_inspect_dialog_key(
        &mut self,
        event: &KeyDownEvent,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some((choices, at)) = self.inspect_dialog.as_mut() else {
            return;
        };
        let n = choices.len().max(1);
        // The first and the last choice (`SPEC-0275` v19 behaviour 47).
        if let Some(to) = crate::list_nav::edge(&event.keystroke, choices.len()) {
            *at = to;
            cx.stop_propagation();
            cx.notify();
            return;
        }
        match event.keystroke.key.as_str() {
            "down" => *at = (*at + 1) % n,
            "up" => *at = (*at + n - 1) % n,
            "enter" => self.confirm_inspect_dialog(window, cx),
            "escape" => {
                self.inspect_dialog = None;
                self.focus_active(window, cx);
            }
            _ => return,
        }
        cx.stop_propagation();
        cx.notify();
    }

    /// Analyze in the scope dialog: runs Inspect Code over the chosen scope.
    pub fn confirm_inspect_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some((choices, at)) = self.inspect_dialog.take() else {
            return;
        };
        let scope = choices
            .get(at)
            .cloned()
            .unwrap_or(crate::problems_model::InspectScope::Project);
        self.run_inspection(scope, window, cx);
    }

