    /// Opens the Push dialog with the commits the remote lacks (SPEC-0109 behaviour 3).
    pub fn open_push(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.open_push_of(None, None, window, cx);
    }

    /// The push popup for `branch` (default: the current one), with `up_to` only up to that
    /// commit (`SPEC-0068` v6 behaviour 23, `SPEC-0086` v8 behaviour 17).
    pub fn open_push_of(
        &mut self,
        branch: Option<String>,
        up_to: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.remote_project.is_some() {
            self.remote_open_push(branch, up_to, window, cx);
            return;
        }
        let outgoing = Repo::discover(&self.root)
            .and_then(|r| r.outgoing_of(branch.as_deref(), up_to.as_deref()))
            .map_err(|e| e.to_string());
        self.show_push(outgoing, window, cx);
    }

    /// The push popup for `outgoing` (of this machine or the host).
    pub(super) fn show_push(
        &mut self,
        outgoing: Result<idecraft_vcs::Outgoing, String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let view = cx.new(|cx| crate::PushView::new(outgoing, cx));
        self._push_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, view, event: &crate::PushEvent, window, cx| {
                if let crate::PushEvent::Push = event {
                    let count = view.read(cx).outgoing().map_or(0, |o| o.commits.len());
                    let options = view.read(cx).options(cx);
                    if this.remote_project.is_some() {
                        this.remote_push(options, count, cx);
                    } else {
                        this.remote_operation(
                            "Push".into(),
                            move |r| {
                                let done = r.push_with(&options, idecraft_vcs::REMOTE_TIMEOUT);
                                crate::vcs_ops_model::push_report(&done, count)
                            },
                            cx,
                        );
                    }
                }
                this.push = None;
                this.focus_active(window, cx);
                cx.notify();
            },
        ));
        window.focus(&view.read(cx).focus());
        self.push = Some(view);
        cx.notify();
    }

    /// The Push dialog, if it is open.
    pub fn push_dialog(&self) -> Option<Entity<crate::PushView>> {
        self.push.clone()
    }

    /// Opens Update Project with the last method preselected (`SPEC-0144`).
    pub fn open_update(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let method = crate::appearance::ide_settings(cx).vcs.update_method;
        let ahead = self.branch_state.ahead;
        let view = cx.new(|cx| crate::UpdateView::new(method, cx).with_ahead(ahead));
        self._update_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &crate::UpdateEvent, window, cx| {
                if let crate::UpdateEvent::Run(method) = *event {
                    let mut settings = crate::appearance::ide_settings(cx);
                    if settings.vcs.update_method != method {
                        settings.vcs.update_method = method;
                        if let Err(e) = crate::appearance::set_ide_settings(settings, cx) {
                            this.status = Some(format!("Settings not saved: {e}"));
                        }
                    }
                    this.update_project(method, cx);
                }
                if let crate::UpdateEvent::Reset = *event {
                    this.reset_to_upstream(cx);
                }
                this.update = None;
                this.focus_active(window, cx);
                cx.notify();
            },
        ));
        window.focus(&view.read(cx).focus());
        self.update = Some(view);
        cx.notify();
    }

    /// Opens the interactive rebase dialog for the commits since `onto` (`SPEC-0145`); without
    /// `onto`, since the current branch's upstream.
    pub fn open_rebase(&mut self, onto: &str, window: &mut Window, cx: &mut Context<Self>) {
        if self.remote_project.is_some() {
            if onto.is_empty() {
                self.status =
                    Some("Interactive rebase: start from a commit in the Git log (⌥I)".into());
                cx.notify();
            } else {
                self.remote_open_rebase(onto.to_owned(), None, window, cx);
            }
            return;
        }
        let listed = Repo::discover(&self.root).and_then(|r| {
            let onto = if onto.is_empty() {
                r.tracking()?
                    .into_iter()
                    .find(|t| t.current)
                    .and_then(|t| t.upstream)
                    .ok_or_else(|| {
                        idecraft_vcs::GitError::Rejected(
                            "the branch has no upstream; start from a commit in the Git log (⌥I)"
                                .into(),
                        )
                    })?
            } else {
                onto.to_owned()
            };
            let label = crate::git_ops_model::rebase_base_label(
                &onto,
                r.short_commit_id(&onto).ok().as_deref(),
            );
            Ok((onto.clone(), label, r.rebase_todo(&onto)?))
        });
        let (onto, label, entries) = match listed {
            Ok((_, _, e)) if e.is_empty() => {
                self.status = Some("Interactive rebase: no commits since the base".into());
                cx.notify();
                return;
            }
            Ok(x) => x,
            Err(e) => {
                self.status = Some(format!("Interactive rebase: {e}"));
                cx.notify();
                return;
            }
        };
        let root = self.root.clone();
        self.show_rebase(onto, label, entries, Some(root), window, cx);
    }

    /// The interactive rebase dialog; `root` is `None` for the host's commits (no local details).
    pub(super) fn show_rebase(
        &mut self,
        onto: String,
        label: String,
        entries: Vec<idecraft_vcs::TodoEntry>,
        root: Option<PathBuf>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let view = cx.new(|cx| {
            let mut v = crate::RebaseView::new(onto, label, entries, cx);
            // The selected commit's files and details (SPEC-0145 v3 behaviour 7).
            if let Some(root) = root {
                v.set_root(root, cx);
            }
            v
        });
        self._rebase_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &crate::RebaseEvent, window, cx| {
                if let crate::RebaseEvent::Start(onto, entries) = event {
                    let (onto, entries) = (onto.clone(), entries.clone());
                    if this.remote_project.is_some() {
                        this.remote_rebase(onto, entries, cx);
                    } else {
                        this.git_operation(
                            "Interactive rebase".into(),
                            move |r| r.rebase_interactive(&onto, &entries),
                            cx,
                        );
                    }
                }
                this.rebase = None;
                this.focus_active(window, cx);
                cx.notify();
            },
        ));
        window.focus(&view.read(cx).focus());
        self.rebase = Some(view);
        cx.notify();
    }

    /// The interactive rebase dialog, if it is open.
    pub fn rebase_dialog(&self) -> Option<Entity<crate::RebaseView>> {
        self.rebase.clone()
    }

    /// The Update Project dialog, if it is open.
    pub fn update_dialog(&self) -> Option<Entity<crate::UpdateView>> {
        self.update.clone()
    }

    /// Fetches and merges or rebases the current branch's upstream in the background.
    pub fn update_project(&mut self, method: idecraft_core::UpdateMethod, cx: &mut Context<Self>) {
        if self.remote_project.is_some() {
            self.remote_pull(method == idecraft_core::UpdateMethod::Rebase, cx);
            return;
        }
        self.update_operation(
            "Update".into(),
            move |r| {
                let done = match method {
                    idecraft_core::UpdateMethod::Merge => {
                        r.pull(false, idecraft_vcs::REMOTE_TIMEOUT)
                    }
                    idecraft_core::UpdateMethod::Rebase => {
                        r.pull_rebase(false, idecraft_vcs::REMOTE_TIMEOUT)
                    }
                };
                // What came in opens in the Update Info popup (SPEC-0144 v4 behaviour 8).
                let info = done.as_ref().ok().and_then(|p| p.info.clone());
                (crate::vcs_ops_model::pull_report(&done), info)
            },
            cx,
        );
    }

    /// Runs a fetch, pull or push in the background and puts its report into the status bar; open
    /// editors pick up changed files (SPEC-0109 behaviour 4).
    pub fn remote_operation(
        &mut self,
        label: String,
        op: impl FnOnce(&Repo) -> String + Send + 'static,
        cx: &mut Context<Self>,
    ) {
        let root = self.root.clone();
        self.status = Some(format!("{label}…"));
        cx.notify();
        let task = cx.background_executor().spawn(async move {
            match Repo::discover(&root) {
                Ok(r) => op(&r),
                Err(e) => format!("{label} failed: {e}"),
            }
        });
        cx.spawn(async move |this, cx| {
            let report = task.await;
            let _ = this.update(cx, |this, cx| {
                this.status = Some(report);
                this.close_merge_next = this.merge.is_some();
                this.refresh_branch();
                this.reload_git_log(cx);
                for editor in this.editors.values() {
                    editor.update(cx, |e, cx| e.check_disk(cx));
                }
                cx.notify();
            });
        })
        .detach();
    }

    /// The project popup, if it is open.
    pub fn projects_popup(&self) -> Option<Entity<crate::ProjectsView>> {
        self.projects.clone()
    }

    /// Opens the theme popup of Quick Switch Scheme (SPEC-0060 v5 behaviour 10).
    pub fn open_themes(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let view = cx.new(crate::ThemesView::new);
        self._themes_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, _, event: &crate::ThemesEvent, window, cx| {
                this.themes = None;
                if let crate::ThemesEvent::Choose(theme) = event {
                    this.choose_theme(*theme, cx);
                }
                this.focus_active(window, cx);
                cx.notify();
            },
        ));
        window.focus(&view.read(cx).focus());
        self.themes = Some(view);
        cx.notify();
    }

    /// The project folder this workbench shows.
    pub fn project_root(&self) -> &Path {
        &self.root
    }

    /// Whether the Settings dialog is open: its pages for agent rights, MCP and UI automation are
    /// reserved for the user (SPEC-0319 behaviour 35).
    pub fn settings_open(&self) -> bool {
        self.settings.is_some()
    }

    /// Opens the Settings dialog on `page` (SPEC-0105 behaviour 1).
    pub fn open_settings(
        &mut self,
        page: crate::settings_model::Page,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let extra = idecraft_languages::everywhere::UNBOUND_ACTIONS.to_vec();
        let plugins_dir = self.plugins_dir.clone();
        let root = self.root.clone();
        let view = cx.new(|cx| {
            let mut v = crate::SettingsView::new(page, extra, cx);
            if let Some(dir) = plugins_dir {
                v.set_plugins_dir(dir, cx);
            }
            v.set_root(root, cx);
            v
        });
        self._settings_events = Some(cx.subscribe_in(
            &view,
            window,
            |this, view, event: &crate::SettingsEvent, window, cx| {
                match event {
                    crate::SettingsEvent::Theme(theme) => {
                        this.choose_theme(*theme, cx);
                        view.update(cx, |v, cx| v.reload_ide(cx));
                    }
                    crate::SettingsEvent::Shortcuts(action, shortcuts) => {
                        if let Err(e) = crate::keymaps::set_shortcuts(action, shortcuts.clone(), cx)
                        {
                            this.status = Some(format!("Keymap not saved: {e}"));
                        }
                        // The menu bar shows the new shortcuts (SPEC-0124 behaviour 3).
                        crate::menu_bar::install(cx);
                        view.update(cx, |v, cx| {
                            v.refresh();
                            cx.notify();
                        });
                    }
                    crate::SettingsEvent::PluginsChanged => {
                        this.reload_plugins(cx);
                    }
                    crate::SettingsEvent::Ide(settings) => {
                        if let Err(e) =
                            crate::appearance::set_ide_settings((**settings).clone(), cx)
                        {
                            this.status = Some(format!("Settings not saved: {e}"));
                        }
                        // Open editors take the Code Style at once (SPEC-0150 behaviour 2).
                        for e in this.editors.values() {
                            e.update(cx, |e, cx| {
                                e.reload_editorconfig();
                                cx.notify();
                            });
                        }
                    }
                    crate::SettingsEvent::Close => {
                        this.settings = None;
                        this.focus_active(window, cx);
                    }
                    // Other windows check theirs when they become active (SPEC-0278 behaviour 8).
                    crate::SettingsEvent::TrustChanged => this.refresh_trust(cx),
                    // Open editors follow the profile at once (SPEC-0315 behaviour 3).
                    crate::SettingsEvent::InspectionsChanged => this.reinspect_editors(cx),
                    crate::SettingsEvent::RunInTerminal(command) => {
                        // The program asks for the account in the terminal (SPEC-0160).
                        this.settings = None;
                        this.new_terminal_tab(window, cx);
                        if let Some(t) = this.terminal() {
                            t.update(cx, |t, _| t.send_text(&format!("{command}\n")));
                        }
                    }
                }
                cx.notify();
            },
        ));
        window.focus(&view.read(cx).focus());
        self.settings = Some(view);
        cx.notify();
    }

    /// Opens Settings › Editor › Inspections, with the inspection `id` selected (`SPEC-0315`
    /// behaviour 5).
    pub fn open_inspection_settings(
        &mut self,
        id: Option<&str>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.open_settings(crate::settings_model::Page::Inspections, window, cx);
        if let (Some(id), Some(view)) = (id, self.settings.clone()) {
            view.update(cx, |v, cx| v.select_inspection(id, cx));
        }
    }

