#[cfg(test)]
mod tests {
    use super::{CompareSide, run_compare};

    /// SPEC-0110 v7 AK-16 (OBS-0051 L4): two schemas of one DuckDB file compare, the script
    /// starts in the target's schema and names both sides with their schema.
    #[test]
    fn two_schemas_of_one_connection_compare() {
        let dir = std::env::temp_dir().join(format!("idecraft-two-schemas-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let db = dir.join("d.duckdb");
        let conn = duckdb::Connection::open(&db).unwrap();
        conn.execute_batch(
            "create schema new; create schema old; \
             create table new.w (id integer primary key, city text); \
             create table new.extra (id integer); \
             create table old.w (id integer primary key);",
        )
        .unwrap();
        drop(conn);
        let profile = idecraft_database::ConnectionProfile::from_url(
            "d",
            &format!("duckdb://{}", db.display()),
        )
        .unwrap();
        let side = |schema: &str| CompareSide {
            profile: profile.clone(),
            schema: Some(schema.into()),
            object: None,
        };
        let (run, written) = run_compare(&side("new"), &side("old"), &dir.join("m.sql"));
        assert!(written.is_ok() && !run.failed, "{:?}", run.output);
        assert!(
            run.output[0].0.starts_with("Compared `d.new` with `d.old`"),
            "{:?}",
            run.output
        );
        let tab = run.schema_diff.unwrap();
        let lines: Vec<String> = tab
            .lines
            .iter()
            .map(|l| format!("{}{} {}", "  ".repeat(l.depth), l.mark.sign(), l.text))
            .collect();
        assert!(lines.contains(&"+ table extra".to_owned()), "{lines:?}");
        let script: Vec<&str> = tab.script.lines().collect();
        assert!(
            script[0].starts_with("-- Turns `d.old` into `d.new`"),
            "{script:?}"
        );
        // SPEC-0110 v11 AK-21: the first statement pins the target schema.
        let first =
            idecraft_database::split_statements(&tab.script, idecraft_database::Dialect::DuckDb);
        assert_eq!(first[0].text, "SET search_path TO \"old\"", "{script:?}");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

#[cfg(test)]
mod status_order_tests {
    use super::{Duration, FRESH_NOTE, status_order};

    /// SPEC-0070 v11 behaviour 4c (OBS-0028 T6): the summary of Optimize Imports stands before an
    /// ESLint finding at the caret for a few seconds; later the finding wins, and a language
    /// server's problem always does (the problem after saving, hand test 2026-11-01).
    #[test]
    fn a_fresh_note_stands_before_the_problem_at_the_caret() {
        let s = |t: &str| Some(t.to_owned());
        let problem = s("ESLint: 'a' is never reassigned. Use 'const' instead.");
        let summary = s("Removed 2 unused imports");
        assert_eq!(
            status_order(
                problem.clone(),
                true,
                summary.clone(),
                Some(Duration::ZERO),
                None
            ),
            summary
        );
        assert_eq!(
            status_order(
                problem.clone(),
                true,
                summary.clone(),
                Some(FRESH_NOTE - Duration::from_millis(1)),
                None
            ),
            summary
        );
        assert_eq!(
            status_order(
                problem.clone(),
                true,
                summary.clone(),
                Some(FRESH_NOTE),
                None
            ),
            problem
        );
        // Without a problem the own note, then the editor's note.
        assert_eq!(
            status_order(
                None,
                false,
                summary.clone(),
                Some(FRESH_NOTE * 10),
                s("Read-only")
            ),
            summary
        );
        assert_eq!(
            status_order(None, false, None, None, s("Read-only")),
            s("Read-only")
        );
        assert_eq!(
            status_order(problem.clone(), false, None, None, None),
            problem
        );
        // A language server's problem wins over a fresh note such as "Saved".
        let undeclared = s("clang: use of undeclared identifier 'x'");
        assert_eq!(
            status_order(
                undeclared.clone(),
                false,
                s("Saved"),
                Some(Duration::ZERO),
                None
            ),
            undeclared
        );
    }
}

