/// How long a new status note stands in front of the problem at the caret (SPEC-0070 v11
/// behaviour 4c).
const FRESH_NOTE: Duration = Duration::from_secs(4);

/// What the right of the status bar shows: the problem under the caret before older notes such as
/// "Saved" (SPEC-0070 v2 behaviour 4); but a finding of a tool that runs after each change (ESLint)
/// does not hide a note set less than [`FRESH_NOTE`] ago — the result of what the user just did,
/// such as "Removed 2 unused imports" (v11 behaviour 4c, OBS-0028 T6). A language server's problem
/// keeps winning. Then the editor's own note.
fn status_order(
    problem: Option<String>,
    problem_from_tool: bool,
    own: Option<String>,
    own_age: Option<Duration>,
    note: Option<String>,
) -> Option<String> {
    if problem_from_tool && own_age.is_some_and(|a| a < FRESH_NOTE) {
        own.or(problem).or(note)
    } else {
        problem.or(own).or(note)
    }
}

/// A status note held in front of the problem at the caret (SPEC-0070 v9 behaviour 4a).
#[derive(Debug, Clone, PartialEq, Eq)]
struct StatusHold {
    /// The note, as set in `status`.
    message: String,
    /// The active file when it was reported.
    path: Option<PathBuf>,
    /// The caret of the active editor when it was reported.
    caret: Option<usize>,
    /// A passing hint (behaviour 4b): removed when the hold ends.
    passing: bool,
    /// The hold of a passing hint ended; the note is not shown any more.
    gone: bool,
}

/// The active file as the toolbar's Run and Debug judged it (SPEC-0061 v17 behaviour 66): the
/// project model is read again only when another file becomes active.
struct RunFile {
    path: PathBuf,
    revision: u64,
    model: idecraft_core::ProjectModel,
    runnable: bool,
}

/// Where the Run/Debug, Generate or another choice popup stands.
#[derive(Debug, Clone, PartialEq, Eq)]
enum JvmPopupPlace {
    /// At the top of the editor, in the middle.
    Top,
    /// At the navigation path in the status line (`SPEC-0059` v7 behaviour 14).
    Status,
    /// At the caret it was opened from: file and char offset (`SPEC-0122` v5 behaviour 13).
    Caret(PathBuf, usize),
    /// At a gutter mark: file and char offset of the start of the mark's line (`SPEC-0115` v6
    /// behaviour 17). Under the line at the editor's left edge, or over it without room.
    Mark(PathBuf, usize),
}
